-- =============================================================================
-- 436 — LE CAHIER D'EXERCICES DE TLE (partie 1)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 436 --niveau Tle --matieres allemand,anglais --suffixe 1 > supabase/contenu/436_exercices_tle_1.sql
--
-- 75 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.k137           36 exercices · 12 chapitres
--   anglais.k138            21 exercices · 7 chapitres
--   anglais.k139            18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ff33c871-1fdd-5899-9cf3-a995b1cb8ec5'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Stopp, nicht teilen !","competence":"comprendre-langue","situation":"Lena reçoit une nouvelle alarmante sur son téléphone. Lis sa conversation avec Murat, puis réponds.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Murat","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Hast du die Nachricht gesehen? Die Schule soll ab Montag geschlossen werden!"},{"qui":"Murat","texte":"Woher hast du das? Das ist bestimmt eine Falschmeldung."},{"qui":"Lena","texte":"Es steht in einem Post ohne Quelle."},{"qui":"Murat","texte":"Dann teile es nicht! Erst die Quelle prüfen, dann weitersagen."},{"qui":"Lena","texte":"Stimmt. Auf der Schulwebsite steht nichts davon."},{"qui":"Murat","texte":"Siehst du? Gut, dass du die Nachricht nicht geteilt hast."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche, dans la conversation, le mot qui veut dire « fausse information ».","aide":"Murat porte un jugement sur la nouvelle : cherche son mot composé.","type":"zone","document":"sms","multiple":false},{"enonce":"Que conseille Murat à Lena avant de transmettre une nouvelle ?","aide":"Relis la réplique de Murat qui commence par « Dann teile es nicht ».","type":"choix","options":[{"id":"a","texte":"La supprimer puis quitter définitivement le réseau"},{"id":"b","texte":"La relayer tout de suite pour prévenir les autres"},{"id":"c","texte":"Vérifier d’où vient la nouvelle avant de la relayer"},{"id":"d","texte":"L’envoyer d’abord à toute la classe pour avis"}],"multiple":false},{"enonce":"Où Lena trouve-t-elle la preuve que la nouvelle est fausse ?","aide":"Regarde l’avant-dernière réplique de Lena.","type":"choix","options":[{"id":"a","texte":"Dans un article du journal Der Spiegel"},{"id":"b","texte":"Dans un message de son professeur"},{"id":"c","texte":"Dans une vidéo envoyée par Murat"},{"id":"d","texte":"Sur le site internet de son école"}],"multiple":false},{"enonce":"Associe chaque mot allemand à son sens français.","aide":"« teilen » est aussi le verbe du bouton « partager ».","type":"association","gauche":[{"id":"g0","texte":"die Quelle"},{"id":"g1","texte":"teilen"},{"id":"g2","texte":"die sozialen Netzwerke"},{"id":"g3","texte":"die Falschmeldung"}],"droite":[{"id":"d0","texte":"les réseaux sociaux"},{"id":"d1","texte":"partager"},{"id":"d2","texte":"la source"},{"id":"d3","texte":"la fausse information"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**Falschmeldung** : « falsch » (faux) + « Meldung » (information). C’est le mot que Murat emploie."},{"cle":{"type":"choix","ids":["c"]},"explication":"Murat dit : « Erst die Quelle prüfen, dann weitersagen » : **vérifier la source, puis transmettre**."},{"cle":{"type":"choix","ids":["d"]},"explication":"« Auf der Schulwebsite steht nichts davon » : la preuve est **sur le site de l’école**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**die Quelle** = la source, **teilen** = partager, **die sozialen Netzwerke** = les réseaux sociaux, **die Falschmeldung** = la fausse information."}]$ex$::jsonb),
  ('ff33c871-1fdd-5899-9cf3-a995b1cb8ec5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un clic ou un vrai engagement ?","competence":"analyser-document","situation":"Dans ton lycée, on débat de l’utilité des hashtags. Croise le tableau des mouvements et la discussion de deux élèves.","documents":[{"id":"mouv","type":"tableau","titre":"Drei Bewegungen im Netz","colonnes":["Bewegung","Thema"],"lignes":[["#aufschrei (2013)","Sexismus im Alltag"],["#MeTwo (2018)","Rassismus im Alltag"],["Fridays for Future","Klimaschutz und Demonstrationen"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"},{"id":"debatte","type":"texte","genre":"article","titre":"Die Diskussion","blocs":["Jonas findet: Ein Klick auf „Gefällt mir“ ist noch kein Engagement. Wer wirklich etwas ändern will, muss mehr tun.","Hannah widerspricht: Ein Hashtag eröffnet die Debatte, die dann auf der Straße und bei den Wahlen weitergeht. Sie hat selbst eine Online-Petition an den Bundestag unterschrieben."],"source":"Discussion écrite pour l’exercice"}],"questions":[{"enonce":"Touche, dans le tableau, la case qui donne le thème du mouvement #MeTwo.","aide":"Cherche la ligne #MeTwo, puis la colonne « Thema ».","type":"zone","document":"mouv","multiple":false},{"enonce":"Quel est l’argument de Jonas ?","aide":"Relis le premier paragraphe.","type":"choix","options":[{"id":"a","texte":"Un simple clic ne remplace pas un véritable engagement"},{"id":"b","texte":"Les pétitions envoyées au Bundestag ne sont pas reconnues"},{"id":"c","texte":"Les réseaux sociaux ne servent qu’à faire rire les élèves"},{"id":"d","texte":"Les hashtags sont interdits par la loi allemande"}],"multiple":false},{"enonce":"Quelle réponse Hannah lui oppose-t-elle ?","aide":"Cherche ce que fait le hashtag selon elle : « eröffnet die Debatte ».","type":"choix","options":[{"id":"a","texte":"Les hashtags doivent disparaître pour protéger la démocratie"},{"id":"b","texte":"Le hashtag lance un débat que la rue et les urnes poursuivent"},{"id":"c","texte":"Seules les élections comptent, pas le débat public en ligne"},{"id":"d","texte":"Le clic suffit à tout changer, la rue devient donc inutile"}],"multiple":false},{"enonce":"Complète la phrase sur la pétition de Hannah.","aide":"On adresse une pétition « à » quelqu’un.","type":"trous","segments":["Sie hat eine Online-Petition ",0," den Bundestag unterschrieben."],"banque":["nach","in","an","mit"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**Rassismus im Alltag** : #MeTwo rassemble des témoignages de racisme vécu au quotidien."},{"cle":{"type":"choix","ids":["a"]},"explication":"Pour Jonas, **un clic n’est pas un engagement** : il faut « mehr tun », faire davantage."},{"cle":{"type":"choix","ids":["b"]},"explication":"Hannah pense que le hashtag **ouvre le débat**, qui continue ensuite dans la rue et aux élections."},{"cle":{"type":"trous","trous":[["an"]]},"affichage":"an","explication":"On écrit une pétition **an** den Bundestag (accusatif) : elle lui est adressée."}]$ex$::jsonb),
  ('ff33c871-1fdd-5899-9cf3-a995b1cb8ec5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"NetzDG, Deepfakes : qui règle le jeu ?","competence":"analyser-texte","situation":"Un journal lycéen publie un dossier sur les règles d’Internet en Allemagne et en Europe. Lis-le attentivement.","documents":[{"id":"dossier","type":"texte","genre":"article","titre":"Regeln für das Netz","blocs":["Seit 2017 verpflichtet das Netzwerkdurchsetzungsgesetz (NetzDG) große Plattformen dazu, offensichtlich rechtswidrige Inhalte schnell zu löschen.","Kritiker fürchten, dass die Plattformen im Zweifel zu viel löschen und damit die Meinungsfreiheit einschränken. Befürworter antworten, dass die Hassrede Menschen aus der Debatte vertreibt.","Inzwischen hat auch die Europäische Union das Thema übernommen. Künstlich erzeugte Bilder und Stimmen, sogenannte Deepfakes, müssen künftig gekennzeichnet werden."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche, dans l’article, le mot qui veut dire « discours de haine ».","aide":"C’est un mot composé : « Hass » signifie la haine.","type":"zone","document":"dossier","multiple":false},{"enonce":"Quelle crainte les critiques de la loi expriment-ils ?","aide":"Cherche le verbe « löschen » (supprimer) dans la deuxième phrase.","type":"choix","options":[{"id":"a","texte":"Que les utilisateurs quittent massivement les réseaux sociaux"},{"id":"b","texte":"Que les plateformes suppriment trop de contenus par précaution"},{"id":"c","texte":"Que les plateformes ne suppriment plus aucun contenu du tout"},{"id":"d","texte":"Que l’État prenne le contrôle de tous les journaux du pays"}],"multiple":false},{"enonce":"Pourquoi les partisans de la loi la défendent-ils ?","aide":"Relis la fin du deuxième paragraphe : que fait la Hassrede ?","type":"choix","options":[{"id":"a","texte":"Parce que les plateformes gagneraient ainsi plus d’argent"},{"id":"b","texte":"Parce que la haine éloigne certaines personnes du débat public"},{"id":"c","texte":"Parce que l’Union européenne l’a imposée à l’Allemagne en 2017"},{"id":"d","texte":"Parce que les utilisateurs souhaitent rester anonymes en ligne"}],"multiple":false},{"enonce":"Complète la phrase au passif.","aide":"Passif : werden + participe II, avec un verbe modal devant.","type":"trous","segments":["Deepfakes ",0," künftig gekennzeichnet ",1,"."],"banque":["haben","werden","müssen","sind"]},{"enonce":"Associe chaque mot à sa traduction.","aide":"Relis les deux premiers paragraphes pour retrouver ces mots.","type":"association","gauche":[{"id":"g0","texte":"die Plattform"},{"id":"g1","texte":"löschen"},{"id":"g2","texte":"rechtswidrig"},{"id":"g3","texte":"die Meinungsfreiheit"}],"droite":[{"id":"d0","texte":"la plateforme"},{"id":"d1","texte":"la liberté d’expression"},{"id":"d2","texte":"illégal"},{"id":"d3","texte":"supprimer"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"**die Hassrede** : « Hass » (haine) + « Rede » (discours)."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les critiques craignent que les plateformes **suppriment trop** (« zu viel löschen ») et limitent la liberté d’expression."},{"cle":{"type":"choix","ids":["b"]},"explication":"La Hassrede « vertreibt Menschen aus der Debatte » : pour les partisans, **la haine chasse des gens du débat**."},{"cle":{"type":"trous","trous":[["mussen"],["werden"]]},"affichage":"müssen · werden","explication":"Le passif avec modal : **müssen** … gekennzeichnet **werden** (« doivent être signalés »)."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**löschen** = supprimer, **rechtswidrig** = contraire au droit, donc illégal, **die Meinungsfreiheit** = la liberté d’expression."}]$ex$::jsonb),
  ('5b3bdc41-23b2-56c4-b8d8-1685a0f84532'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Kulturtag in Weimar","competence":"analyser-document","situation":"Ta classe d’allemand prépare une sortie à Weimar, la ville de Goethe et de Schiller. Lis l’affiche du programme.","documents":[{"id":"plakat","type":"fiche","modele":"affiche","entete":"Kulturtag in Weimar","sousTitre":"Samstag, 10 Uhr – Treffpunkt: Theaterplatz","emoji":"🎭","lignes":[{"texte":"Führung: Auf den Spuren von Goethe und Schiller","id":"z1"},{"texte":"Besuch im Deutschen Nationaltheater","id":"z2"},{"separateur":true},{"texte":"Lesung: Gedichte der Romantik","id":"z3"},{"texte":"Eintritt: 8 €, Schüler 4 €","id":"z4"}],"pied":"Anmeldung bis Freitag im Sekretariat","teinte":"violet","source":"Affiche imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la ligne de l’affiche qui annonce une lecture de poèmes.","aide":"« Gedichte » veut dire poèmes.","type":"zone","document":"plakat","multiple":false},{"enonce":"Combien un élève paie-t-il l’entrée, en euros ?","aide":"Regarde la ligne « Eintritt » : le plein tarif et le tarif élève.","type":"nombre","unite":"€"},{"enonce":"Quand et à quelle heure commence la sortie ?","aide":"Attention : le vendredi est la date limite d’inscription.","type":"choix","options":[{"id":"a","texte":"Le samedi, à quatorze heures"},{"id":"b","texte":"Le vendredi, à dix heures"},{"id":"c","texte":"Le dimanche, à dix heures"},{"id":"d","texte":"Le samedi, à dix heures"}],"multiple":false},{"enonce":"Associe chaque mot de l’affiche à son sens.","aide":"Pense à ce que tu fais avant d’entrer dans un musée.","type":"association","gauche":[{"id":"g0","texte":"die Führung"},{"id":"g1","texte":"die Lesung"},{"id":"g2","texte":"der Eintritt"},{"id":"g3","texte":"die Anmeldung"}],"droite":[{"id":"d0","texte":"la lecture publique"},{"id":"d1","texte":"la visite guidée"},{"id":"d2","texte":"l’inscription"},{"id":"d3","texte":"le prix d’entrée"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Lesung: Gedichte der Romantik** : une lecture de poèmes romantiques."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 €","explication":"« Schüler 4 € » : un élève paie **4 euros**."},{"cle":{"type":"choix","ids":["d"]},"explication":"« Samstag, 10 Uhr » : **le samedi à dix heures**. Le vendredi est seulement la date limite d’inscription."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**Führung** = visite guidée, **Lesung** = lecture publique, **Eintritt** = entrée (et son prix), **Anmeldung** = inscription."}]$ex$::jsonb),
  ('5b3bdc41-23b2-56c4-b8d8-1685a0f84532'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Brecht au lycée : faire réfléchir","competence":"analyser-texte","situation":"Le club de théâtre de ton lycée monte une pièce de Bertolt Brecht. Lis l’article du journal de l’établissement.","documents":[{"id":"presse","type":"texte","genre":"article","titre":"Eine Schulaufführung von Brecht","blocs":["Die Theater-AG unseres Gymnasiums führt „Mutter Courage und ihre Kinder“ von Bertolt Brecht auf. Die Schauspieler sprechen manchmal direkt zum Publikum, und Schilder erklären, was passiert. Das Publikum soll nicht weinen, sondern nachdenken.","Die Regisseurin erklärt, dass die Zuschauer immer daran denken sollen: Wir sind im Theater. Deshalb nennt man diese Technik den Verfremdungseffekt."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot allemand qui désigne l’effet de distanciation.","aide":"C’est un très long mot composé, dans le deuxième paragraphe.","type":"zone","document":"presse","multiple":false},{"enonce":"Pourquoi les acteurs s’adressent-ils directement au public ?","aide":"Relis la phrase qui commence par « Die Regisseurin erklärt ».","type":"choix","options":[{"id":"a","texte":"Pour demander de l’argent aux spectateurs à la sortie"},{"id":"b","texte":"Pour rappeler aux spectateurs qu’ils sont au théâtre"},{"id":"c","texte":"Parce qu’ils ont oublié leur texte pendant la répétition"},{"id":"d","texte":"Pour que les spectateurs oublient qu’ils sont au théâtre"}],"multiple":false},{"enonce":"Complète la phrase avec la conjonction qui oppose les deux idées.","aide":"Après une négation, on oppose avec « mais plutôt ».","type":"trous","segments":["Das Publikum soll nicht weinen, ",0," nachdenken."],"banque":["weil","sondern","aber","denn"]},{"enonce":"Range chaque caractéristique dans la bonne colonne.","aide":"Brecht veut faire réfléchir, pas faire pleurer.","type":"categories","categories":[{"id":"c0","texte":"Théâtre traditionnel"},{"id":"c1","texte":"Théâtre de Brecht"}],"items":[{"id":"i0","texte":"Les acteurs parlent au public"},{"id":"i1","texte":"Des pancartes expliquent l’action"},{"id":"i2","texte":"Le spectateur s’identifie et pleure"},{"id":"i3","texte":"On veut faire oublier qu’on est au théâtre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m53"]},"explication":"**der Verfremdungseffekt** : l’effet qui rend le théâtre « étrange » pour que le spectateur réfléchisse."},{"cle":{"type":"choix","ids":["b"]},"explication":"La metteuse en scène veut que les spectateurs pensent : « Wir sind im Theater ». Les acteurs **rappellent donc qu’on est au théâtre**."},{"cle":{"type":"trous","trous":[["sondern"]]},"affichage":"sondern","explication":"**nicht … sondern** : « non pas pleurer, mais réfléchir »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Chez **Brecht** : adresse au public, pancartes, réflexion. Le **théâtre traditionnel** cherche l’identification et l’illusion."}]$ex$::jsonb),
  ('5b3bdc41-23b2-56c4-b8d8-1685a0f84532'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quatre artistes, quatre scènes","competence":"analyser-document","situation":"Tu prépares un exposé sur la culture allemande. Croise le tableau et le petit texte de présentation.","documents":[{"id":"kuenstler","type":"tableau","titre":"Vier Künstler","colonnes":["Name","Kunstform","Werk"],"lignes":[["Fritz Lang","Film","Metropolis (1927)"],["Maren Ade","Film","Toni Erdmann (2016)"],["Pina Bausch","Tanztheater","Tanztheater Wuppertal"],["Bertolt Brecht","Theater","Mutter Courage (geschrieben 1939)"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"},{"id":"steckbrief","type":"texte","genre":"article","titre":"Wer ist wer ?","blocs":["Eine Choreografin leitete ab 1973 in Wuppertal ein Ensemble, in dem die Tänzer auch sprachen und lachten.","Ein Regisseur zeigte 1927 eine Stadt der Zukunft, in der die Arbeiter unter der Erde lebten.","Eine Regisseurin gewann 2016 mit einer Komödie über einen Vater und seine Tochter internationale Aufmerksamkeit."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Associe chaque description à la bonne personne.","aide":"Croise les dates et les œuvres du tableau avec les trois phrases du texte.","type":"association","gauche":[{"id":"g0","texte":"Elle dirige à Wuppertal un « théâtre dansé »"},{"id":"g1","texte":"Il montre des ouvriers qui vivent sous terre"},{"id":"g2","texte":"Elle réalise en 2016 une comédie père-fille"},{"id":"g3","texte":"Il écrit une pièce sur une femme en temps de guerre"}],"droite":[{"id":"d0","texte":"Bertolt Brecht"},{"id":"d1","texte":"Pina Bausch"},{"id":"d2","texte":"Maren Ade"},{"id":"d3","texte":"Fritz Lang"}]},{"enonce":"Touche la case du tableau qui donne l’œuvre de Fritz Lang.","aide":"Cherche la ligne de Fritz Lang, puis la colonne « Werk ».","type":"zone","document":"kuenstler","multiple":false},{"enonce":"Dans « ein Ensemble, in dem die Tänzer auch sprachen », quel mot le pronom relatif « dem » reprend-il ?","aide":"« in dem » est masculin ou neutre au datif : quel nom convient ?","type":"choix","options":[{"id":"a","texte":"Tänzer"},{"id":"b","texte":"Ensemble"},{"id":"c","texte":"Wuppertal"},{"id":"d","texte":"Choreografin"}],"multiple":false},{"enonce":"Complète la phrase avec la préposition qui convient.","aide":"Dans le film, la ville est au-dessus, les ouvriers sont en dessous.","type":"trous","segments":["Die Arbeiter lebten ",0," der Erde."],"banque":["hinter","neben","über","unter"]},{"enonce":"Combien d’années séparent le film Metropolis de l’écriture de Mutter Courage ?","aide":"Soustrais les deux dates du tableau.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"Wuppertal et 1973 : **Pina Bausch** ; 1927, la ville du futur : **Fritz Lang** ; 2016, père et fille : **Maren Ade** ; *Mutter Courage* : **Brecht**."},{"cle":{"type":"zone","ids":["r0c2"]},"explication":"**Metropolis (1927)** est le film de Fritz Lang."},{"cle":{"type":"choix","ids":["b"]},"explication":"« dem » reprend **das Ensemble** (neutre, datif après « in ») : le groupe où les danseurs parlent aussi."},{"cle":{"type":"trous","trous":[["unter"]]},"affichage":"unter","explication":"Les ouvriers de Metropolis vivent **unter** der Erde : sous la terre."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 ans","explication":"1939 − 1927 = **12 ans**."}]$ex$::jsonb),
  ('e42ff1a4-10cd-5b56-a0d7-2b9b806b939c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Slogans : ce qu’ils racontent","competence":"analyser-document","situation":"Un professeur affiche trois slogans célèbres au tableau. Lis ce tableau.","documents":[{"id":"slogans","type":"tableau","titre":"Drei Slogans","colonnes":["Slogan","Wer / Wann"],"lignes":[["Vorsprung durch Technik","Werbung eines Autoherstellers"],["Wir sind das Volk","Demonstrationen, 1989"],["Mehr Demokratie wagen","Willy Brandt, 1969"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le slogan qui a été scandé lors des manifestations de 1989.","aide":"Regarde la colonne de droite : cherche « 1989 ».","type":"zone","document":"slogans","multiple":false},{"enonce":"En quelle année Willy Brandt a-t-il lancé sa formule ?","aide":"La date est dans la dernière ligne du tableau.","type":"nombre"},{"enonce":"Associe chaque slogan à son contexte.","aide":"Relis la colonne « Wer / Wann ».","type":"association","gauche":[{"id":"g0","texte":"Vorsprung durch Technik"},{"id":"g1","texte":"Wir sind das Volk"},{"id":"g2","texte":"Mehr Demokratie wagen"}],"droite":[{"id":"d0","texte":"un programme politique de 1969"},{"id":"d1","texte":"les manifestations de 1989"},{"id":"d2","texte":"une publicité automobile"}]},{"enonce":"Complète la phrase de vocabulaire.","aide":"Un slogan doit convaincre.","type":"trous","segments":["Ein guter Slogan ist kurz und soll die Leute ",0,"."],"banque":["überzeugen","ärgern","vergessen","verbieten"]}]}$ex$::jsonb,
