  ('e42ff1a4-10cd-5b56-a0d7-2b9b806b939c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"9 novembre 1989 : une phrase, un Mur","competence":"analyser-texte","situation":"Une chronique imaginée revient sur la soirée du 9 novembre 1989. Lis-la.","documents":[{"id":"abend","type":"texte","genre":"article","titre":"Der Abend des 9. November 1989","blocs":["Am Abend des 9. November 1989 gibt Günter Schabowski, Mitglied des Politbüros der SED, eine Pressekonferenz im Fernsehen. Ein Journalist fragt, ab wann die neue Reiseregelung gilt. Schabowski sucht in seinen Papieren und antwortet unsicher: „Sofort, unverzüglich.“","Noch in der Nacht öffnen sich die Grenzübergänge in Berlin, und tausende Ostberliner gehen nach Westberlin."],"source":"Chronique écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui disent à quel moment la règle s’applique, selon Schabowski.","aide":"Il répond à la question « ab wann ? » (à partir de quand).","type":"zone","document":"abend","multiple":true},{"enonce":"Pourquoi le Mur tombe-t-il cette nuit-là ?","aide":"Relis la réponse de Schabowski, puis le dernier paragraphe.","type":"choix","options":[{"id":"a","texte":"L’armée reçoit l’ordre de démolir le Mur pendant la nuit"},{"id":"b","texte":"La Stasi ouvre ses archives aux journalistes étrangers"},{"id":"c","texte":"Les habitants de l’Ouest attaquent les postes de frontière"},{"id":"d","texte":"Les habitants comprennent que la frontière est ouverte immédiatement"}],"multiple":false},{"enonce":"Remets les faits dans l’ordre de l’article.","aide":"Suis le récit paragraphe par paragraphe.","type":"ordre","items":[{"id":"a","texte":"Des milliers de gens passent à l’Ouest"},{"id":"b","texte":"Schabowski répond avec hésitation"},{"id":"c","texte":"Un journaliste pose une question sur la date"},{"id":"d","texte":"Les postes-frontières s’ouvrent"}]},{"enonce":"Complète la question indirecte.","aide":"« À partir de quand » se dit avec une préposition qui marque le début.","type":"trous","segments":["Ein Journalist fragt, ",0," wann die neue Regelung gilt."],"banque":["ab","bis","nach","seit"]},{"enonce":"Dans « ab wann die neue Reiseregelung gilt », pourquoi « gilt » est-il à la fin ?","aide":"Dans une subordonnée, où va le verbe conjugué ?","type":"choix","options":[{"id":"a","texte":"Parce que la phrase est racontée au passé composé"},{"id":"b","texte":"Parce que c’est une question indirecte introduite par « ab wann »"},{"id":"c","texte":"Parce que « gilt » est un verbe de modalité qui se place en dernier"},{"id":"d","texte":"Parce que « Reiseregelung » est un nom composé à l’accusatif"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m35","m36"]},"explication":"**Sofort** et **unverzüglich** : « tout de suite, sans délai »."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec « sofort, unverzüglich », beaucoup comprennent que **la frontière s’ouvre tout de suite** : ils se rendent aux postes-frontières."},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"Question du journaliste, réponse hésitante, ouverture des postes-frontières, puis passage de milliers de gens à l’Ouest."},{"cle":{"type":"trous","trous":[["ab"]]},"affichage":"ab","explication":"**ab wann** : « à partir de quand ». Le verbe « gilt » part à la fin de la subordonnée interrogative."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est une **subordonnée interrogative indirecte** : le verbe conjugué part à la fin."}]$ex$::jsonb),
