   $ex${"titre":"Quand une formule se retourne","competence":"analyser-document","situation":"En 1990, une promesse politique a fait date. Croise le tableau des formules célèbres et l’éditorial de la journaliste.","documents":[{"id":"formeln","type":"tableau","titre":"Drei berühmte Formeln","colonnes":["Formel","Wer","Jahr"],"lignes":[["Ich bin ein Berliner","John F. Kennedy","1963"],["Mehr Demokratie wagen","Willy Brandt","1969"],["blühende Landschaften","Helmut Kohl","1990"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"},{"id":"kommentar","type":"texte","genre":"article","titre":"Ein Kommentar","blocs":["Helmut Kohl versprach 1990 den Ostdeutschen „blühende Landschaften“. Viele Menschen glaubten ihm. Doch schon wenige Jahre später verloren Millionen Menschen ihre Arbeit, weil viele Fabriken schließen mussten.","Aus dem Versprechen wurde ein Spottwort: Wer heute von „blühenden Landschaften“ spricht, meint oft das Gegenteil."],"source":"Commentaire écrit pour l’exercice"}],"questions":[{"enonce":"Touche, dans l’éditorial, le nom qui veut dire « promesse ».","aide":"Le verbe « versprach » du premier paragraphe est de la même famille.","type":"zone","document":"kommentar","multiple":false},{"enonce":"Pourquoi la formule « blühende Landschaften » est-elle devenue ironique ?","aide":"Lis la fin du premier paragraphe : que perdent des centaines de milliers de gens ?","type":"choix","options":[{"id":"a","texte":"Parce que le chancelier a retiré sa promesse en 1990"},{"id":"b","texte":"Parce que le chômage a frappé l’Est malgré la promesse"},{"id":"c","texte":"Parce que l’Ouest a refusé d’aider les régions de l’Est"},{"id":"d","texte":"Parce que les paysages de l’Est ont été détruits"}],"multiple":false},{"enonce":"Associe chaque formule à son effet.","aide":"Utilise les dates du tableau et ton cours.","type":"association","gauche":[{"id":"g0","texte":"Ich bin ein Berliner"},{"id":"g1","texte":"Mehr Demokratie wagen"},{"id":"g2","texte":"blühende Landschaften"}],"droite":[{"id":"d0","texte":"Programme de réformes"},{"id":"d1","texte":"Solidarité avec Berlin-Ouest"},{"id":"d2","texte":"Promesse devenue ironique"}]},{"enonce":"Complète la dernière phrase.","aide":"Le sens de la formule s’est inversé.","type":"trous","segments":["Wer von „blühenden Landschaften“ spricht, meint oft das ",0,"."],"banque":["Ende","Ziel","Gleiche","Gegenteil"]},{"enonce":"Combien d’années séparent la formule de Brandt de celle de Kohl ?","aide":"Utilise les deux années du tableau.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"**das Versprechen** : la promesse, devenue un sujet de moquerie."},{"cle":{"type":"choix","ids":["b"]},"explication":"Des centaines de milliers de personnes ont perdu leur emploi : **la réalité contredit la promesse**, d’où l’ironie."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Kennedy (1963) : solidarité ; Brandt (1969) : réformes ; Kohl (1990) : promesse ensuite tournée en dérision."},{"cle":{"type":"trous","trous":[["gegenteil"]]},"affichage":"Gegenteil","explication":"Le **Gegenteil** : le contraire de ce que la formule disait."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 ans","explication":"1990 − 1969 = **21 ans**."}]$ex$::jsonb),
