   $ex${"titre":"Les femmes et le droit : une frise","competence":"se-reperer-temps","situation":"Tu prépares une affiche sur l’émancipation des femmes en Allemagne. Lis la frise.","documents":[{"id":"frise","type":"frise","titre":"Frauenrechte in Deutschland","debut":1900,"fin":2010,"pas":10,"evenements":[{"id":"z1","date":1918,"nom":"Frauenwahlrecht"},{"id":"z2","date":1949,"nom":"Grundgesetz"},{"id":"z3","date":1977,"nom":"Ehemann-Regel fällt"},{"id":"z4","date":2005,"nom":"Kanzlerin Merkel"}],"source":"Frise écrite pour l’exercice. « Ehemann-Regel fällt » : la femme mariée n’a plus besoin de l’accord de son mari pour travailler (RFA)."}],"questions":[{"enonce":"Touche l’événement qui correspond au droit de vote des femmes.","aide":"« Wahlrecht » signifie droit de vote.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le droit de vote des femmes de l’élection de la première chancelière ?","aide":"Soustrais les deux années de la frise.","type":"nombre","unite":"ans"},{"enonce":"Qu’est-ce qui change en 1977 en RFA ?","aide":"Lis la source sous la frise.","type":"choix","options":[{"id":"a","texte":"Une femme devient pour la première fois ministre fédérale"},{"id":"b","texte":"Une femme mariée obtient le droit de vote aux élections"},{"id":"c","texte":"Une femme peut pour la première fois entrer à l’université"},{"id":"d","texte":"Une femme mariée peut travailler sans l’accord de son mari"}],"multiple":false},{"enonce":"Complète la phrase de la Loi fondamentale.","aide":"L’article défend l’égalité des droits.","type":"trous","segments":["Männer und Frauen sind ",0,"."],"banque":["verheiratet","ähnlich","gleichberechtigt","unterschiedlich"]}]}$ex$::jsonb,
