  ('e458f10b-13b6-5f04-85fd-86d036afb913'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Ma fiche Stasi","competence":"analyser-texte","situation":"Anja a lu son dossier après la chute de la RDA. Lis son témoignage, imaginé pour l’exercice.","documents":[{"id":"zeugnis","type":"texte","genre":"lettre","titre":"Anjas Geschichte","blocs":["Als ich 1992 meine Akte las, konnte ich es nicht glauben. Mein Nachbar und sogar ein Freund hatten der Stasi über mich berichtet. Ich wusste nicht, dass jemand so genau aufgeschrieben hatte, wann ich nach Hause kam und wer mich besuchte.","Heute achte ich sehr darauf, wer meine Daten hat."],"source":"Témoignage imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui veut dire « dossier, fiche ».","aide":"Anja lit quelque chose sur elle-même : qu’est-ce ?","type":"zone","document":"zeugnis","multiple":false},{"enonce":"Qu’est-ce qui choque le plus Anja dans son dossier ?","aide":"Relis la deuxième phrase.","type":"choix","options":[{"id":"a","texte":"Que la police politique ait détruit toutes ses archives"},{"id":"b","texte":"Que des proches aient rapporté sa vie à la police politique"},{"id":"c","texte":"Que ses voisins aient reçu de l’argent du gouvernement"},{"id":"d","texte":"Que son dossier soit resté secret pendant toute sa vie"}],"multiple":false},{"enonce":"Quel temps exprime « hatten … berichtet » ?","aide":"Repère l’auxiliaire : « hatten » est lui-même au prétérit.","type":"choix","options":[{"id":"a","texte":"Le plus-que-parfait"},{"id":"b","texte":"Le prétérit"},{"id":"c","texte":"Le parfait"},{"id":"d","texte":"Le futur antérieur"}],"multiple":false},{"enonce":"Complète la préposition.","aide":"« Rapporter sur quelqu’un ».","type":"trous","segments":["Mein Nachbar hat der Stasi ",0," mich berichtet."],"banque":["über","auf","gegen","für"]},{"enonce":"Associe chaque mot à sa traduction.","aide":"Relis le témoignage et ton cours de vocabulaire.","type":"association","gauche":[{"id":"g0","texte":"die Akte"},{"id":"g1","texte":"die Überwachung"},{"id":"g2","texte":"der Datenschutz"},{"id":"g3","texte":"die Stasi"}],"droite":[{"id":"d0","texte":"le dossier"},{"id":"d1","texte":"la protection des données"},{"id":"d2","texte":"la surveillance"},{"id":"d3","texte":"la police politique de la RDA"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**die Akte** : le dossier que la Stasi avait constitué sur Anja."},{"cle":{"type":"choix","ids":["b"]},"explication":"Son **voisin et un ami** ont parlé d’elle à la Stasi : c’est la trahison de proches qui la bouleverse."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Hatten + participe II** = plus-que-parfait : ces rapports étaient antérieurs au moment où Anja lit son dossier."},{"cle":{"type":"trous","trous":[["uber"]]},"affichage":"über","explication":"On dit « berichten **über** + accusatif » : rapporter sur quelqu’un."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**Akte** = dossier, **Überwachung** = surveillance, **Datenschutz** = protection des données, **Stasi** = police politique de la RDA."}]$ex$::jsonb),
