   $ex${"titre":"Street View : pourquoi tant de méfiance ?","competence":"analyser-document","situation":"En 2010, beaucoup d’Allemands ont refusé que leur maison apparaisse sur Internet. Croise l’article et le tableau des repères.","documents":[{"id":"streetview","type":"texte","genre":"article","titre":"Die Deutschen und ihre Daten","blocs":["2010 startete Google Street View in Deutschland. Hunderttausende Menschen beantragten, dass ihr Haus unkenntlich gemacht wird. Wer keinen Widerspruch einlegte, sah sein Haus im Internet.","Viele Deutsche erklären ihre Skepsis mit der Geschichte: Wer von der Gestapo oder der Stasi beobachtet wurde, weiß, was Daten wert sind."],"source":"Article écrit pour l’exercice"},{"id":"daten","type":"tableau","titre":"Drei Daten","colonnes":["Jahr","Was geschah ?"],"lignes":[["1983","Das Bundesverfassungsgericht erkennt das Recht auf informationelle Selbstbestimmung an"],["2010","Häuser werden bei Street View unkenntlich gemacht"],["2018","Die europäische DSGVO gilt"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux organisations de surveillance citées dans l’article.","aide":"Elles sont nommées dans la dernière phrase.","type":"zone","document":"streetview","multiple":true},{"enonce":"Quelle explication de leur méfiance beaucoup d’Allemands donnent-ils ?","aide":"Relis la dernière phrase de l’article.","type":"choix","options":[{"id":"a","texte":"Leur pays a interdit Internet pendant plusieurs années"},{"id":"b","texte":"Leur histoire leur a appris la valeur des données privées"},{"id":"c","texte":"Leurs banques ont perdu des données importantes en 2010"},{"id":"d","texte":"Leur langue n’existe pas dans les services de Google"}],"multiple":false},{"enonce":"Dans « Wer keinen Widerspruch einlegte, sah sein Haus im Internet », que représente « wer » ?","aide":"Le verbe « einlegte » est à la fin : est-ce une question ?","type":"choix","options":[{"id":"a","texte":"« pour que » : une subordonnée de but"},{"id":"b","texte":"« parce que » : une subordonnée de cause"},{"id":"c","texte":"« celui qui » : une relative sans antécédent"},{"id":"d","texte":"« qui ? » : une question directe"}],"multiple":false},{"enonce":"Combien d’années séparent la décision de 1983 de l’entrée en vigueur du RGPD (DSGVO) en 2018 ?","aide":"Utilise le tableau des trois dates.","type":"nombre","unite":"ans"},{"enonce":"Complète le nom du droit créé en 1983.","aide":"C’est le droit de décider soi-même de ses données.","type":"trous","segments":["Das Recht auf informationelle ",0," wurde 1983 anerkannt."],"banque":["Überwachung","Gleichberechtigung","Werbung","Selbstbestimmung"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m36","m39"]},"explication":"La **Gestapo** (police nazie) et la **Stasi** (police politique de la RDA)."},{"cle":{"type":"choix","ids":["b"]},"explication":"Ceux qui ont été surveillés par la Gestapo ou la Stasi **savent ce que valent leurs données** : l’histoire explique la méfiance."},{"cle":{"type":"choix","ids":["c"]},"explication":"« **Wer … einlegte** » = « celui qui n’a pas fait opposition » : une relative sans antécédent."},{"cle":{"type":"nombre","valeur":35,"tolerance":0},"affichage":"35 ans","explication":"2018 − 1983 = **35 ans**."},{"cle":{"type":"trous","trous":[["selbstbestimmung"]]},"affichage":"Selbstbestimmung","explication":"Le droit à l’autodétermination informationnelle : **informationelle Selbstbestimmung**."}]$ex$::jsonb),
