   $ex${"titre":"Le miracle de Berne raconté par un grand-père","competence":"analyser-texte","situation":"Pour un exposé, Nico interroge son grand-père sur la finale de la Coupe du monde de 1954. Lis son récit, imaginé pour l’exercice.","documents":[{"id":"opa","type":"texte","genre":"article","titre":"Opa erzählt","blocs":["Mein Großvater erinnert sich noch genau an den 4. Juli 1954. Die deutsche Mannschaft spielte in Bern im Finale der Weltmeisterschaft gegen Ungarn, den großen Favoriten. Nach einem 0:2 gewann Deutschland am Ende mit 3:2.","„Wir waren wieder wer“, sagt er. Nach dem Krieg hatten viele Menschen das Gefühl gehabt, nichts mehr zu sein. Der Sieg gab ihnen neues Selbstvertrauen."],"source":"Récit imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui désigne l’équipe que tout le monde donnait gagnante.","aide":"Ungarn était « le grand … » : quel nom suit l’adjectif « großen » ?","type":"zone","document":"opa","multiple":false},{"enonce":"De combien de buts l’Allemagne était-elle menée au plus fort du match ?","aide":"Regarde le score « 0:2 ».","type":"nombre"},{"enonce":"Pourquoi ce match compte-t-il au-delà du football ?","aide":"Relis le deuxième paragraphe : comment se sentaient les gens après la guerre ?","type":"choix","options":[{"id":"a","texte":"Il met fin à la division du pays en deux États allemands"},{"id":"b","texte":"Il fait oublier la défaite subie lors de la guerre de 1914"},{"id":"c","texte":"Il redonne confiance à un pays qui se sentait réduit à rien"},{"id":"d","texte":"Il prouve que l’Allemagne a désormais les meilleurs clubs"}],"multiple":false},{"enonce":"Complète la phrase au plus-que-parfait.","aide":"Le verbe « haben » forme son plus-que-parfait avec lui-même.","type":"trous","segments":["Nach dem Krieg ",0," viele Menschen das Gefühl ",1,", nichts mehr zu sein."],"banque":["hatten","waren","gehabt","gewesen"]}]}$ex$::jsonb,
