  ('70f21318-eef6-5f3a-b7b7-b1116b0f6db5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Sophie Scholl et Quex : deux figures opposées","competence":"analyser-document","situation":"Un professeur compare une résistante réelle et un héros fabriqué. Lis les deux présentations.","documents":[{"id":"scholl","type":"texte","genre":"article","titre":"Sophie Scholl","blocs":["Sophie Scholl studierte in München. Mit der Weißen Rose verteilte sie Flugblätter gegen Hitler. Am 22. Februar 1943 wurde sie hingerichtet. Heute gilt sie als Vorbild für Zivilcourage."],"source":"Présentation écrite pour l’exercice"},{"id":"quex","type":"texte","genre":"article","titre":"Hitlerjunge Quex","blocs":["Der Film „Hitlerjunge Quex“ kam 1933 in die Kinos. Er erzählt von einem Jungen, der für die Nazis stirbt, und macht ihn zum Märtyrer. Der Film sollte Jugendliche für die Hitlerjugend begeistern."],"source":"Présentation écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit pourquoi Sophie Scholl est un modèle aujourd’hui.","aide":"C’est un mot qui désigne le courage d’un citoyen face à l’injustice.","type":"zone","document":"scholl","multiple":false},{"enonce":"Range chaque élément sous la bonne figure.","aide":"Une seule des deux figures a réellement existé comme résistante.","type":"categories","categories":[{"id":"c0","texte":"Sophie Scholl"},{"id":"c1","texte":"Hitlerjunge Quex"}],"items":[{"id":"i0","texte":"Modèle de courage civique aujourd’hui"},{"id":"i1","texte":"Exécutée en 1943"},{"id":"i2","texte":"Héros d’un film de 1933"},{"id":"i3","texte":"Étudiante de la Rose blanche"},{"id":"i4","texte":"Devient un martyr pour le régime"},{"id":"i5","texte":"Sert à attirer la jeunesse vers la HJ"}]},{"enonce":"Quelle est la différence essentielle entre les deux figures ?","aide":"Croise ce que disent les deux présentations.","type":"choix","options":[{"id":"a","texte":"L’une a réellement résisté, l’autre est une fiction de propagande"},{"id":"b","texte":"L’une a vécu avant 1933, l’autre après la Seconde Guerre mondiale"},{"id":"c","texte":"L’une défend la monarchie, l’autre défend la république"},{"id":"d","texte":"L’une est une figure de théâtre, l’autre une figure de sport"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"« Enthousiasmer pour quelque chose ».","type":"trous","segments":["Der Film sollte Jugendliche ",0," die Hitlerjugend begeistern."],"banque":["von","gegen","ohne","für"]},{"enonce":"Combien d’années séparent le film Hitlerjunge Quex de l’exécution de Sophie Scholl ?","aide":"Utilise 1933 et 1943.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
