  ('9a3a898e-a0a2-5382-888c-542b748b51f9'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Tipps für bessere Noten","competence":"manier-langue","situation":"Le foyer du lycée affiche des conseils pour bien apprendre. Lis l’affiche.","documents":[{"id":"tipps","type":"fiche","modele":"affiche","entete":"Tipps für bessere Noten","sousTitre":"Vom Schülerrat","emoji":"📚","lignes":[{"texte":"Man lernt Vokabeln, indem man sie in Sätzen benutzt.","id":"z1"},{"texte":"Man verbessert sein Hören, indem man Podcasts hört.","id":"z2"},{"texte":"Man bleibt fit, indem man jeden Tag spazieren geht.","id":"z3"}],"pied":"Probiert es aus!","teinte":"violet","source":"Affiche imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le conseil qui concerne le vocabulaire.","aide":"« Vokabeln » signifie mots de vocabulaire.","type":"zone","document":"tipps","multiple":false},{"enonce":"Complète le conseil sur l’écoute.","aide":"Après « indem », le verbe conjugué va à la fin : quelle forme avec « man » ?","type":"trous","segments":["Man verbessert sein Hören, indem man Podcasts ",0,"."],"banque":["gehört","hört","hörte","hören"]},{"enonce":"Quelle phrase dit la même chose que « Man bleibt fit, indem man jeden Tag spazieren geht » ?","aide":"« indem » exprime le moyen, comme « durch » + nom.","type":"choix","options":[{"id":"a","texte":"Man bleibt fit, bevor man jeden Tag spazieren geht."},{"id":"b","texte":"Man bleibt fit, obwohl man jeden Tag spazieren geht."},{"id":"c","texte":"Man bleibt fit durch tägliches Spazierengehen."},{"id":"d","texte":"Man bleibt fit, weil man nie draußen spazieren geht."}],"multiple":false},{"enonce":"Associe chaque mot de l’affiche à sa traduction.","aide":"Reprends les conseils ligne par ligne.","type":"association","gauche":[{"id":"g0","texte":"der Tipp"},{"id":"g1","texte":"die Vokabel"},{"id":"g2","texte":"spazieren gehen"},{"id":"g3","texte":"verbessern"}],"droite":[{"id":"d0","texte":"le mot de vocabulaire"},{"id":"d1","texte":"aller se promener"},{"id":"d2","texte":"le conseil"},{"id":"d3","texte":"améliorer"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Man lernt Vokabeln, indem man sie in Sätzen benutzt** : on retient mieux les mots en les utilisant dans des phrases."},{"cle":{"type":"trous","trous":[["hort"]]},"affichage":"hört","explication":"Après « man », le verbe prend **-t** : « indem man Podcasts hört » (en écoutant des podcasts)."},{"cle":{"type":"choix","ids":["c"]},"explication":"« indem » = le moyen ; « **durch** tägliches Spazierengehen » dit la même chose avec un nom."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**Tipp** = conseil, **Vokabel** = mot de vocabulaire, **spazieren gehen** = se promener, **verbessern** = améliorer."}]$ex$::jsonb),
  ('9a3a898e-a0a2-5382-888c-542b748b51f9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une ville qui change l’air","competence":"analyser-texte","situation":"Un journal régional présente une ville imaginaire qui a réduit la pollution. Lis l’article.","documents":[{"id":"stadt","type":"texte","genre":"article","titre":"Bessere Luft in der Mittelstadt","blocs":["Eine deutsche Mittelstadt hat die Luftqualität verbessert. Sie hatte dadurch Erfolg, dass sie den Autoverkehr im Zentrum begrenzt hat.","Die Bürger sparen Zeit, indem sie mit dem Fahrrad fahren, und die Geschäfte haben nicht weniger Kunden, ohne dass jemand dafür Geld bekommen hat."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce la subordonnée de moyen en « dass ».","aide":"Il commence par « da- » et contient « durch ».","type":"zone","document":"stadt","multiple":false},{"enonce":"Comment la ville a-t-elle amélioré la qualité de l’air ?","aide":"Relis la phrase avec « dadurch, dass ».","type":"choix","options":[{"id":"a","texte":"En interdisant toutes les voitures dans la ville entière"},{"id":"b","texte":"En limitant la circulation automobile dans le centre"},{"id":"c","texte":"En construisant une grande route autour de la ville"},{"id":"d","texte":"En offrant des vélos gratuits à tous les habitants"}],"multiple":false},{"enonce":"Complète la phrase de moyen.","aide":"Le moyen « en faisant quelque chose ».","type":"trous","segments":["Die Bürger sparen Zeit, ",0," sie mit dem Fahrrad fahren."],"banque":["obwohl","seit","bevor","indem"]},{"enonce":"Dans « ohne dass jemand dafür Geld bekommen hat », pourquoi emploie-t-on « dass » plutôt que « ohne … zu » ?","aide":"Compare le sujet de la principale et celui de la subordonnée.","type":"choix","options":[{"id":"a","texte":"Parce que « ohne » exige toujours « dass » après une virgule"},{"id":"b","texte":"Parce que le mot « Geld » est un nom neutre au datif pluriel"},{"id":"c","texte":"Parce que la phrase est écrite au parfait et non au présent"},{"id":"d","texte":"Parce que son sujet diffère de celui de la principale"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**dadurch** : il annonce « dass … » et met le moyen en avant."},{"cle":{"type":"choix","ids":["b"]},"explication":"« dadurch, dass sie den Autoverkehr im Zentrum begrenzt hat » : **en limitant la circulation au centre**."},{"cle":{"type":"trous","trous":[["indem"]]},"affichage":"indem","explication":"**indem** exprime le moyen : « en allant à vélo »."},{"cle":{"type":"choix","ids":["d"]},"explication":"Quand les sujets diffèrent, on emploie **ohne dass** ; « ohne … zu » suppose le même sujet."}]$ex$::jsonb),
  ('9a3a898e-a0a2-5382-888c-542b748b51f9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Fake News : mode d’emploi","competence":"manier-langue","situation":"La rédaction d’un journal lycéen publie un guide contre les infox. Lis-le, puis analyse ses constructions.","documents":[{"id":"ratgeber","type":"texte","genre":"article","titre":"Wie erkennt man Fake News ?","blocs":["Man kann Fake News bekämpfen, indem man die Quellen überprüft. Wer eine Nachricht teilt, ohne sie gelesen zu haben, hilft der Falschmeldung, sich zu verbreiten.","Statt sofort auf „Teilen“ zu klicken, sollte man kurz nachdenken. Eine Redaktion gewinnt Vertrauen dadurch, dass sie ihre Fehler offen zugibt."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque expression du texte selon le sens qu’elle exprime.","aide":"« indem » et « dadurch, dass » répondent à la même question : comment ?","type":"categories","categories":[{"id":"c0","texte":"Le moyen"},{"id":"c1","texte":"Sans faire"},{"id":"c2","texte":"Au lieu de faire"}],"items":[{"id":"i0","texte":"dadurch, dass sie ihre Fehler offen zugibt"},{"id":"i1","texte":"indem man die Quellen überprüft"},{"id":"i2","texte":"Statt sofort auf „Teilen“ zu klicken"},{"id":"i3","texte":"ohne sie gelesen zu haben"}]},{"enonce":"Complète la phrase pour traduire « en comparant plusieurs journaux ».","aide":"Après « indem », le verbe conjugué est en dernière position.","type":"trous","segments":["Er schützt sich vor Falschmeldungen, ",0," er mehrere Zeitungen ",1,"."],"banque":["indem","vergleichen","vergleicht","ohne"]},{"enonce":"Complète la phrase pour traduire « sans l’avoir lue ».","aide":"Même sujet dans les deux propositions : « ohne … zu » + infinitif.","type":"trous","segments":["Er teilt die Nachricht, ",0," sie gelesen ",1," haben."],"banque":["zu","indem","ohne","dass"]},{"enonce":"Quelle phrase est correcte quand les deux sujets sont différents ?","aide":"Sujets différents : « ohne dass » + verbe conjugué en fin de phrase.","type":"choix","options":[{"id":"a","texte":"Die Nachricht verbreitet sich, ohne dass jemand sie prüft."},{"id":"b","texte":"Die Nachricht verbreitet sich, indem niemand sie prüfen."},{"id":"c","texte":"Die Nachricht verbreitet sich, ohne jemand sie zu prüfen."},{"id":"d","texte":"Die Nachricht verbreitet sich, ohne dass jemand sie zu prüfen."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c2","i3":"c1"}},"explication":"**indem** et **dadurch, dass** : le moyen ; **ohne … zu** : sans faire ; **statt … zu** : au lieu de faire."},{"cle":{"type":"trous","trous":[["indem"],["vergleicht"]]},"affichage":"indem · vergleicht","explication":"**indem** … **vergleicht** : le moyen, avec le verbe à la fin."},{"cle":{"type":"trous","trous":[["ohne"],["zu"]]},"affichage":"ohne · zu","explication":"**ohne … zu haben** : « sans avoir lu », puisque le sujet est le même."},{"cle":{"type":"choix","ids":["a"]},"explication":"**ohne dass jemand sie prüft** : « dass » + verbe conjugué en dernière position."}]$ex$::jsonb),
  ('097dce0a-cc15-54cf-84c9-50cc85c10e06'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Komm doch mit !","competence":"comprendre-langue","situation":"Mia essaie de convaincre Jan de sortir la veille d’un examen. Lis leurs messages.","documents":[{"id":"chat","type":"dialogue","modele":"sms","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Was ist denn los? Du bist so still."},{"qui":"Jan","texte":"Ich habe ja morgen die Prüfung."},{"qui":"Mia","texte":"Komm doch mit ins Kino! Das lenkt dich ab."},{"qui":"Jan","texte":"Ich sollte wohl lieber lernen."},{"qui":"Mia","texte":"Komm mal raus, nur zwei Stunden."},{"qui":"Jan","texte":"Na gut. Aber nur kurz."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la particule qui transforme l’invitation en invitation insistante.","aide":"Mia dit « Komm … mit ins Kino ! » : quelle petite particule ajoute l’insistance ?","type":"zone","document":"chat","multiple":false},{"enonce":"Dans « Ich sollte wohl lieber lernen », que montre « wohl » ?","aide":"« wohl » ajoute l’idée de « sans doute ».","type":"choix","options":[{"id":"a","texte":"Une supposition, une hésitation de la part de Jan"},{"id":"b","texte":"Un ordre que Jan donne à son amie pour ce soir"},{"id":"c","texte":"Une question que Jan pose à son amie sur le film"},{"id":"d","texte":"Une certitude que Jan affirme sans aucun doute"}],"multiple":false},{"enonce":"Associe chaque phrase à la nuance de sa particule.","aide":"Reprends les messages un par un.","type":"association","gauche":[{"id":"g0","texte":"Was ist denn los?"},{"id":"g1","texte":"Komm doch mit!"},{"id":"g2","texte":"Komm mal raus!"},{"id":"g3","texte":"Ich habe ja morgen die Prüfung."}],"droite":[{"id":"d0","texte":"évidence que l’autre connaît"},{"id":"d1","texte":"demande adoucie"},{"id":"d2","texte":"invitation insistante"},{"id":"d3","texte":"intérêt dans une question"}]},{"enonce":"Quelle phrase est la plus naturelle pour demander poliment de l’aide ?","aide":"Une particule qui adoucit la demande.","type":"choix","options":[{"id":"a","texte":"Helfen Sie mir eben nicht?"},{"id":"b","texte":"Könnten Sie mir mal helfen?"},{"id":"c","texte":"Sie helfen mir ja gar nicht."},{"id":"d","texte":"Helfen Sie mir wohl sofort!"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**doch** : « Komm doch mit ! » = « Viens donc ! », une invitation insistante."},{"cle":{"type":"choix","ids":["a"]},"explication":"**wohl** exprime la supposition : Jan hésite, « je ferais sans doute mieux de travailler »."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**denn** : intérêt ; **doch** : insistance ; **mal** : adoucit ; **ja** : « tu sais bien que »."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Könnten Sie mir mal helfen ?** : « mal » et le conditionnel rendent la demande polie."}]$ex$::jsonb),
  ('097dce0a-cc15-54cf-84c9-50cc85c10e06'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le même mot, plusieurs tons","competence":"comprendre-langue","situation":"Dans un cours d’allemand, le professeur note quatre phrases avec la situation qui les explique. Lis le tableau.","documents":[{"id":"toene","type":"tableau","titre":"Vier Situationen","colonnes":["Satz","Situation"],"lignes":[["Das Wetter ist ja schön!","Die Sonne scheint plötzlich, niemand hat es erwartet."],["Er kommt wohl nicht mehr.","Niemand weiß es genau, aber es ist schon spät."],["Komm doch mal vorbei!","Eine Freundin lädt freundlich ein."],["Es regnet eben.","Man kann nichts dagegen tun."]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la situation qui décrit une simple supposition.","aide":"Dans laquelle personne n’est sûr de rien ?","type":"zone","document":"toene","multiple":false},{"enonce":"Associe chaque phrase à la nuance exprimée.","aide":"La colonne « Situation » donne les indices.","type":"association","gauche":[{"id":"g0","texte":"Das Wetter ist ja schön!"},{"id":"g1","texte":"Er kommt wohl nicht mehr."},{"id":"g2","texte":"Komm doch mal vorbei!"},{"id":"g3","texte":"Es regnet eben."}],"droite":[{"id":"d0","texte":"la résignation"},{"id":"d1","texte":"l’invitation amicale"},{"id":"d2","texte":"la surprise"},{"id":"d3","texte":"la supposition"}]},{"enonce":"Complète la phrase avec la particule qui marque la supposition.","aide":"Personne n’est sûr : on suppose.","type":"trous","segments":["Niemand weiß es genau, der Zug hat ",0," Verspätung."],"banque":["wohl","ja","mal","denn"]},{"enonce":"Quelle traduction rend le mieux « Es regnet eben » ?","aide":"La colonne « Situation » dit : « Man kann nichts dagegen tun ».","type":"choix","options":[{"id":"a","texte":"Il ne pleut pas, contrairement à ce que tu crois."},{"id":"b","texte":"Il pleut, c’est comme ça, on n’y peut rien."},{"id":"c","texte":"Il pleut donc, contrairement à ce que tu disais."},{"id":"d","texte":"Il pleut enfin après une longue période sèche."}],"multiple":false},{"enonce":"Pourquoi ne traduit-on pas les particules mot à mot ?","aide":"Que ajoutent-elles à la phrase : une information ou une attitude ?","type":"choix","options":[{"id":"a","texte":"Parce qu’elles n’existent qu’à l’écrit formel"},{"id":"b","texte":"Parce qu’elles changent le ton plus que l’information"},{"id":"c","texte":"Parce qu’elles remplacent le verbe de la phrase"},{"id":"d","texte":"Parce qu’elles sont toujours accentuées à l’oral"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**« Niemand weiß es genau »** : c’est le terrain de « wohl », la supposition."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"**ja** : surprise ; **wohl** : supposition ; **doch mal** : invitation amicale ; **eben** : résignation."},{"cle":{"type":"trous","trous":[["wohl"]]},"affichage":"wohl","explication":"**wohl** : « le train a sans doute du retard »."},{"cle":{"type":"choix","ids":["b"]},"explication":"**eben** marque la résignation : « c’est comme ça »."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les particules ajoutent **un ton** (surprise, insistance, supposition), pas une information nouvelle."}]$ex$::jsonb),
  ('097dce0a-cc15-54cf-84c9-50cc85c10e06'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Lire entre les lignes","competence":"analyser-texte","situation":"Dans un récit écrit pour l’exercice, une mère accueille son fils. Les petites particules disent ce qu’elle pense. Lis le texte.","documents":[{"id":"szene","type":"texte","genre":"recit","titre":"An der Tür","blocs":["Frau Keller öffnete die Tür. „Ach, du bist es!“, sagte sie. „Du hast ja den Schlüssel vergessen.“","Ihr Sohn zuckte mit den Schultern. „Es ist doch nicht so schlimm.“","„Das habe ich mir wohl gedacht“, antwortete sie und schüttelte den Kopf. „Komm, wir essen erst mal.“"],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre particules modales du texte.","aide":"Ce sont de petits mots qui ne changent pas l’information : cherche « ja », « doch », « wohl » et « mal ».","type":"zone","document":"szene","multiple":true},{"enonce":"Quelle est l’attitude de Frau Keller face à la situation ?","aide":"Regarde « ja » et « wohl » dans ses deux répliques.","type":"choix","options":[{"id":"a","texte":"Elle n’a rien remarqué et reste indifférente"},{"id":"b","texte":"Elle se met en colère et punit immédiatement son fils"},{"id":"c","texte":"Elle s’y attendait, avec une pointe d’ironie"},{"id":"d","texte":"Elle est ravie et très surprise de la nouvelle"}],"multiple":false},{"enonce":"Dans « Es ist doch nicht so schlimm », que fait « doch » ?","aide":"Le fils répond à un petit reproche.","type":"choix","options":[{"id":"a","texte":"Il exprime une surprise joyeuse devant la remarque de sa mère"},{"id":"b","texte":"Il pose poliment une question à sa mère sur l’oubli de la clé"},{"id":"c","texte":"Il insiste pour minimiser et contredire la remarque de sa mère"},{"id":"d","texte":"Il marque que le fils est sûr de sa supposition sur la clé"}],"multiple":false},{"enonce":"Comment traduire au mieux « Du hast ja den Schlüssel vergessen » ?","aide":"« ja » montre ici une évidence que l’on constate.","type":"choix","options":[{"id":"a","texte":"Tu as oublié la clé, quelle chance !"},{"id":"b","texte":"Tu as oublié la clé, peut-être ?"},{"id":"c","texte":"Tu n’as pas oublié la clé du tout."},{"id":"d","texte":"Tu as oublié la clé, je vois bien."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m25","m33","m45"]},"explication":"**ja**, **doch**, **wohl** et **mal** : les quatre particules qui donnent le ton de la scène."},{"cle":{"type":"choix","ids":["c"]},"explication":"« ja » (évidence) et « wohl gedacht » (je m’en doutais) montrent qu’**elle s’y attendait**, avec un peu d’ironie."},{"cle":{"type":"choix","ids":["c"]},"explication":"**doch** insiste et contredit : « mais ce n’est pas si grave ! »."},{"cle":{"type":"choix","ids":["d"]},"explication":"**ja** marque l’évidence : « je vois bien que tu as oublié la clé »."}]$ex$::jsonb),
