   $ex${"titre":"Dans la presse : participes en vue","competence":"manier-langue","situation":"Voici quelques phrases de presse sur le logement et la nature. Repère les participes.","documents":[{"id":"presse","type":"texte","genre":"article","titre":"Schlagzeilen","blocs":["Die steigenden Mieten machen vielen Familien Sorgen.","Der Preis für eine kleine Wohnung ist in zehn Jahren stark gestiegen.","Die gestiegenen Kosten treffen besonders Studenten.","Im Park sieht man ein lesendes Kind und die blühenden Bäume."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les trois participes présents (participes I) employés comme adjectifs.","aide":"Le participe I se termine par -d + la terminaison d’adjectif.","type":"zone","document":"presse","multiple":true},{"enonce":"Que signifie « die gestiegenen Kosten » ?","aide":"« gestiegen » est un participe II : action accomplie.","type":"choix","options":[{"id":"a","texte":"les coûts qui ont été supprimés"},{"id":"b","texte":"les coûts qui augmentent en ce moment"},{"id":"c","texte":"les coûts qu’il faudra augmenter"},{"id":"d","texte":"les coûts qui ont augmenté"}],"multiple":false},{"enonce":"Associe chaque participe à sa traduction.","aide":"Participe I = action en cours ; participe II = action terminée.","type":"association","gauche":[{"id":"g0","texte":"steigend"},{"id":"g1","texte":"blühend"},{"id":"g2","texte":"lesend"},{"id":"g3","texte":"gestiegen"}],"droite":[{"id":"d0","texte":"qui lit"},{"id":"d1","texte":"qui a augmenté"},{"id":"d2","texte":"qui fleurit"},{"id":"d3","texte":"qui augmente"}]},{"enonce":"Transforme la relative en groupe participial.","aide":"Action en cours → participe I + terminaison.","type":"trous","segments":["Die Mieten steigen. = Die ",0," Mieten machen Sorgen."],"banque":["gestiegen","steigen","gestiegenen","steigenden"]}]}$ex$::jsonb,
