   $ex${"titre":"Un musée, des artistes bannis","competence":"analyser-texte","situation":"Un article de presse annonce l’ouverture d’un musée. Les groupes participiaux y sont nombreux. Lis-le.","documents":[{"id":"museum","type":"texte","genre":"article","titre":"Neues Museum eröffnet","blocs":["Die Stadt hat ein neues Museum eröffnet. Die im Jahr 1920 gegründete Sammlung zeigt die von den Nazis verbannten Künstler. Die seit Jahren erwartete Ausstellung ist ein großer Erfolg."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le nom noyau du groupe « die von den Nazis verbannten … ».","aide":"Saute le groupe participial : quel nom arrive après « verbannten » ?","type":"zone","document":"museum","multiple":false},{"enonce":"Comment traduire « die seit Jahren erwartete Ausstellung » ?","aide":"« erwartete » est un participe II : on attend une idée d’accompli ou de passif.","type":"choix","options":[{"id":"a","texte":"l’exposition attendue depuis des années"},{"id":"b","texte":"l’exposition qui sera attendue un jour"},{"id":"c","texte":"l’exposition qu’il faudra attendre des années"},{"id":"d","texte":"l’exposition qui attend depuis des années"}],"multiple":false},{"enonce":"Transforme le groupe participial en relative.","aide":"Une relative passive : participe II + « wurde ».","type":"trous","segments":["Die im Jahr 1920 gegründete Sammlung = Die Sammlung, die im Jahr 1920 ",0," ",1,"."],"banque":["gründete","gegründet","wurde","hat"]},{"enonce":"Range chaque groupe selon le participe qu’il contient.","aide":"Le participe I finit par -d, le participe II commence souvent par ge-.","type":"categories","categories":[{"id":"c0","texte":"Participe I (en cours)"},{"id":"c1","texte":"Participe II (accompli)"}],"items":[{"id":"i0","texte":"die steigenden Preise"},{"id":"i1","texte":"die blühende Landschaft"},{"id":"i2","texte":"die verbannten Künstler"},{"id":"i3","texte":"die schlafenden Kinder"},{"id":"i4","texte":"das verabschiedete Gesetz"}]}]}