  ('49bf2071-e993-57db-882d-a546aa90d5ae'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Décoder une phrase dense","competence":"analyser-texte","situation":"Un éditorial utilise de longs groupes participiaux. Lis-le en cherchant d’abord les noms.","documents":[{"id":"leitartikel","type":"texte","genre":"article","titre":"Leben in der Großstadt","blocs":["Die in den letzten Jahren stark gestiegene Zahl der in Großstädten lebenden Menschen stellt die Politik vor neue Probleme.","Besonders die seit Jahren steigenden Mieten sind ein nicht zu unterschätzendes Risiko für den sozialen Frieden."],"source":"Éditorial écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nom auquel se rapporte le groupe « in den letzten Jahren stark gestiegene ».","aide":"Après l’article « die », saute le groupe participial jusqu’au premier nom.","type":"zone","document":"leitartikel","multiple":false},{"enonce":"Comment traduire « die in Großstädten lebenden Menschen » ?","aide":"« lebenden » est un participe I : action en cours.","type":"choix","options":[{"id":"a","texte":"les gens qui vivent dans les grandes villes"},{"id":"b","texte":"les gens qu’on a fait vivre en ville"},{"id":"c","texte":"les gens qui vivront dans les grandes villes"},{"id":"d","texte":"les gens qui vivaient dans les grandes villes"}],"multiple":false},{"enonce":"Que signifie « ein nicht zu unterschätzendes Risiko » ?","aide":"« zu » + participe I exprime ce qui doit ou peut être fait.","type":"choix","options":[{"id":"a","texte":"un risque à ne pas sous-estimer"},{"id":"b","texte":"un risque déjà sous-estimé"},{"id":"c","texte":"un risque sans importance"},{"id":"d","texte":"un risque qui sous-estime tout"}],"multiple":false},{"enonce":"Transforme la relative en groupe participial.","aide":"Action en cours : participe I.","type":"trous","segments":["Die Menschen, die in Großstädten leben = Die in Großstädten ",0," Menschen."],"banque":["leben","gelebten","lebt","lebenden"]},{"enonce":"Remets les mots dans l’ordre pour dire « les loyers qui augmentent depuis des années ».","aide":"Le groupe s’intercale entre l’article et le nom.","type":"ordre","items":[{"id":"a","texte":"Mieten"},{"id":"b","texte":"seit"},{"id":"c","texte":"die"},{"id":"d","texte":"steigenden"},{"id":"e","texte":"Jahren"}]}]}$ex$::jsonb,
