  ('a989aac1-5277-5abc-b828-75e21160ec96'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Où est passé mon portable ?","competence":"comprendre-langue","situation":"Léa a perdu son téléphone. Lis ses messages avec Tim.","documents":[{"id":"chat","type":"dialogue","modele":"sms","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Hast du irgendwo mein Handy gesehen?"},{"qui":"Tim","texte":"Nein, ich habe es nirgends gesehen."},{"qui":"Lea","texte":"Irgendjemand muss es doch haben!"},{"qui":"Tim","texte":"Hast du mit jemandem gesprochen?"},{"qui":"Lea","texte":"Nein, mit niemandem. Ich habe nichts gehört."},{"qui":"Tim","texte":"Vielleicht liegt es irgendwo im Bus."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui veut dire « nulle part ».","aide":"C’est l’opposé de « irgendwo » dans la première réplique.","type":"zone","document":"chat","multiple":false},{"enonce":"Où Tim propose-t-il de chercher le téléphone ?","aide":"Relis la dernière réplique de Tim.","type":"choix","options":[{"id":"a","texte":"Quelque part dans le bus"},{"id":"b","texte":"Chez les parents de Léa"},{"id":"c","texte":"Devant la porte du lycée"},{"id":"d","texte":"Dans le sac de Tim"}],"multiple":false},{"enonce":"Associe chaque mot à son sens.","aide":"Les mots en « irgend- » sont positifs ; les autres sont des négations.","type":"association","gauche":[{"id":"g0","texte":"irgendwo"},{"id":"g1","texte":"niemand"},{"id":"g2","texte":"nichts"},{"id":"g3","texte":"irgendjemand"}],"droite":[{"id":"d0","texte":"rien"},{"id":"d1","texte":"personne"},{"id":"d2","texte":"quelque part"},{"id":"d3","texte":"quelqu’un"}]},{"enonce":"Complète la phrase (« rien »).","aide":"Il faut un pronom : rien.","type":"trous","segments":["Er hat ",0," gehört."],"banque":["nie","kein","nicht","nichts"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**nirgends** : nulle part (synonyme : nirgendwo)."},{"cle":{"type":"choix","ids":["a"]},"explication":"« Vielleicht liegt es irgendwo im Bus » : **quelque part dans le bus**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**irgendwo** = quelque part, **niemand** = personne, **nichts** = rien, **irgendjemand** = quelqu’un."},{"cle":{"type":"trous","trous":[["nichts"]]},"affichage":"nichts","explication":"**nichts** : « il n’a rien entendu ». Une seule négation suffit en allemand."}]$ex$::jsonb),
  ('a989aac1-5277-5abc-b828-75e21160ec96'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un exposé pas comme les autres","competence":"analyser-texte","situation":"Dans la classe de Terminale 12 b, chaque élève présente un sujet de son choix. Lis le compte rendu du délégué.","documents":[{"id":"bericht","type":"texte","genre":"article","titre":"Etwas Neues in der 12 b","blocs":["In der 12 b wird etwas Neues ausprobiert: Jeder Schüler darf irgendwann ein Thema vorstellen, das ihn interessiert. Gestern sprach Emre über nichts Besonderes, nur über sein Hobby, und trotzdem hörte ihm jeder zu.","Niemand langweilte sich, und irgendeine Schülerin stellte sogar noch eine Frage. Nirgends sonst in der Schule gibt es so etwas."],"source":"Compte rendu imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs substantivés, écrits avec une majuscule.","aide":"Ils suivent « etwas » et « nichts » et se terminent en -es.","type":"zone","document":"bericht","multiple":true},{"enonce":"Que signifie « irgendeine Schülerin » ?","aide":"Le préfixe « irgend- » ajoute l’idée d’indétermination.","type":"choix","options":[{"id":"a","texte":"toutes les élèves sans exception de la classe"},{"id":"b","texte":"une élève quelconque, on ne sait pas laquelle"},{"id":"c","texte":"toujours la même élève, la meilleure de la classe"},{"id":"d","texte":"aucune élève, car personne n’ose parler"}],"multiple":false},{"enonce":"Quelle phrase dit « Je n’ai rien vu de spécial » ?","aide":"Une seule négation, et l’adjectif prend une majuscule après « nichts ».","type":"choix","options":[{"id":"a","texte":"Ich habe nicht nichts Besonderes gesehen."},{"id":"b","texte":"Ich habe nichts Besonderes gesehen."},{"id":"c","texte":"Ich habe kein Besonderes gesehen."},{"id":"d","texte":"Ich habe nichts besondere gesehen."}],"multiple":false},{"enonce":"Associe chaque mot du texte à sa traduction.","aide":"Reprends les mots du compte rendu.","type":"association","gauche":[{"id":"g0","texte":"irgendwann"},{"id":"g1","texte":"nirgends"},{"id":"g2","texte":"nichts"},{"id":"g3","texte":"niemand"}],"droite":[{"id":"d0","texte":"un jour ou l’autre"},{"id":"d1","texte":"personne"},{"id":"d2","texte":"rien"},{"id":"d3","texte":"nulle part"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m23"]},"explication":"**Neues** (après etwas) et **Besonderes** (après nichts) : adjectifs devenus des noms neutres."},{"cle":{"type":"choix","ids":["b"]},"explication":"**irgendeine** = « une … quelconque » : l’élève n’est pas nommée."},{"cle":{"type":"choix","ids":["b"]},"explication":"**nichts Besonderes** : majuscule et terminaison -es ; jamais deux négations."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**irgendwann** = un jour, **nirgends** = nulle part, **nichts** = rien, **niemand** = personne."}]$ex$::jsonb),
  ('a989aac1-5277-5abc-b828-75e21160ec96'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui a sonné à la porte ?","competence":"analyser-texte","situation":"Un voisin raconte un petit mystère. Lis son témoignage, écrit pour l’exercice, puis analyse les indéfinis.","documents":[{"id":"zeugnis","type":"texte","genre":"lettre","titre":"Ein seltsamer Abend","blocs":["Gestern hat irgendwer bei mir geklingelt, aber niemand stand vor der Tür. Ich habe die Nachbarn gefragt, doch keiner wusste etwas.","Irgendwie ist das unheimlich. Später habe ich mit niemandem mehr darüber gesprochen. Heute habe ich im Flur nichts Auffälliges gefunden, und nirgendwo lag ein Zettel."],"source":"Témoignage imaginé pour l’exercice"}],"questions":[{"enonce":"Range chaque mot du texte selon qu’il est indéfini positif ou négatif.","aide":"« irgend- » marque l’indétermination ; « nie-, nichts, nirgend- » marquent le rien.","type":"categories","categories":[{"id":"c0","texte":"Indéfini positif"},{"id":"c1","texte":"Négation"}],"items":[{"id":"i0","texte":"nirgendwo"},{"id":"i1","texte":"nichts Auffälliges"},{"id":"i2","texte":"niemand"},{"id":"i3","texte":"etwas"},{"id":"i4","texte":"irgendwer"},{"id":"i5","texte":"irgendwie"}]},{"enonce":"Pourquoi écrit-on « mit niemandem » ?","aide":"Quel cas gouverne la préposition « mit » ?","type":"choix","options":[{"id":"a","texte":"Parce que « niemand » est un adjectif devenu nom neutre"},{"id":"b","texte":"Parce que l’accusatif de « niemand » est « niemandem »"},{"id":"c","texte":"Parce que la préposition « mit » est toujours suivie du datif"},{"id":"d","texte":"Parce que « niemand » est un pluriel qui finit en -em"}],"multiple":false},{"enonce":"Pourquoi écrit-on « nichts Auffälliges » avec une majuscule et la terminaison -es ?","aide":"Après « etwas », « nichts », « viel », l’adjectif change de nature.","type":"choix","options":[{"id":"a","texte":"L’adjectif devient un nom neutre après « nichts »"},{"id":"b","texte":"L’adjectif est au génitif masculin après « nichts »"},{"id":"c","texte":"L’adjectif est au datif pluriel après « nichts »"},{"id":"d","texte":"L’adjectif est un participe employé au passé après « nichts »"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Adjectif neutre, avec majuscule.","type":"trous","segments":["Ich habe nichts ",0," gefunden."],"banque":["Auffälliges","auffällig","Auffällige","Auffälligen"]},{"enonce":"Comment traduire « Irgendwie ist das unheimlich » ?","aide":"« irgendwie » = « d’une manière ou d’une autre ».","type":"choix","options":[{"id":"a","texte":"Nulle part ailleurs, ce n’est aussi inquiétant."},{"id":"b","texte":"D’une manière ou d’une autre, c’est inquiétant."},{"id":"c","texte":"Un jour, tout cela deviendra inquiétant."},{"id":"d","texte":"Personne ne trouve cela vraiment inquiétant."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c0"}},"explication":"**Positifs** : irgendwer, etwas, irgendwie. **Négations** : niemand, nichts, nirgendwo."},{"cle":{"type":"choix","ids":["c"]},"explication":"« mit » + **datif** : niemand devient « niemandem »."},{"cle":{"type":"choix","ids":["a"]},"explication":"Après nichts, etwas, viel, wenig : **adjectif substantivé neutre** (majuscule + -es)."},{"cle":{"type":"trous","trous":[["auffalliges"]]},"affichage":"Auffälliges","explication":"**nichts Auffälliges** : « rien de remarquable »."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Irgendwie** = « d’une façon ou d’une autre » : le narrateur ne sait pas expliquer son malaise."}]$ex$::jsonb),
  ('1146abd6-d386-5cb7-b33b-20ce7fb12896'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Hier, j’ai dû travailler","competence":"manier-langue","situation":"Sara et Paul échangent des messages. Observe les verbes composés.","documents":[{"id":"chat","type":"dialogue","modele":"sms","participants":[{"nom":"Sara","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sara","texte":"Warum warst du gestern nicht da?"},{"qui":"Paul","texte":"Ich habe lange arbeiten müssen."},{"qui":"Sara","texte":"Und warum hast du nicht angerufen?"},{"qui":"Paul","texte":"Ich habe nicht anrufen können, mein Handy war kaputt."},{"qui":"Sara","texte":"Hast du es reparieren lassen?"},{"qui":"Paul","texte":"Ja, ich habe es gestern reparieren lassen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes de modalité qui restent à l’infinitif au parfait.","aide":"Ils sont en fin de phrase, après un autre infinitif.","type":"zone","document":"chat","multiple":true},{"enonce":"Complète la phrase au parfait.","aide":"Modal + infinitif : pas de participe.","type":"trous","segments":["Wir haben gestern helfen ",0,"."],"banque":["wollten","wollte","wollen","gewollt"]},{"enonce":"Que signifie « Ich habe es reparieren lassen » ?","aide":"« lassen » + infinitif = faire faire.","type":"choix","options":[{"id":"a","texte":"J’ai réparé cet objet moi-même"},{"id":"b","texte":"J’ai laissé cet objet cassé"},{"id":"c","texte":"J’ai fait réparer cet objet"},{"id":"d","texte":"J’ai voulu réparer cet objet"}],"multiple":false},{"enonce":"Associe chaque phrase au présent à sa forme au parfait.","aide":"Le modal passe à l’infinitif, après l’autre infinitif.","type":"association","gauche":[{"id":"g0","texte":"Ich muss arbeiten."},{"id":"g1","texte":"Er kann kommen."},{"id":"g2","texte":"Wir wollen helfen."}],"droite":[{"id":"d0","texte":"Er hat kommen können."},{"id":"d1","texte":"Wir haben helfen wollen."},{"id":"d2","texte":"Ich habe arbeiten müssen."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m21"]},"explication":"**müssen** et **können** : au parfait, un modal suivi d’un infinitif ne prend pas de participe."},{"cle":{"type":"trous","trous":[["wollen"]]},"affichage":"wollen","explication":"**haben helfen wollen** : double infinitif."},{"cle":{"type":"choix","ids":["c"]},"explication":"**lassen** + infinitif : « faire faire » ; quelqu’un d’autre répare."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Avec un modal suivi d’un infinitif, l’**auxiliaire haben** est suivi de **deux infinitifs**."}]$ex$::jsonb),
  ('1146abd6-d386-5cb7-b33b-20ce7fb12896'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Désolée, Oma !","competence":"manier-langue","situation":"Clara écrit à sa grand-mère pour s’excuser. Lis son e-mail, écrit pour l’exercice.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"E-Mail an Oma","blocs":["Liebe Oma, es tut mir leid, dass ich nicht zu deinem Geburtstag kommen konnte. Du weißt, dass ich lange habe lernen müssen. Du hast mich bestimmt vermisst, weil ich dich nicht habe anrufen können.","Ich hätte dir gern gratuliert. Nächstes Mal will ich dich unbedingt besuchen. Deine Clara"],"source":"E-mail imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les deux auxiliaires placés devant les deux infinitifs.","aide":"Ils sont à l’intérieur d’une subordonnée, avant « lernen müssen » et « anrufen können ».","type":"zone","document":"mail","multiple":true},{"enonce":"Pourquoi l’auxiliaire précède-t-il les deux infinitifs dans « dass ich lange habe lernen müssen » ?","aide":"Normalement, le verbe conjugué est en dernière position.","type":"choix","options":[{"id":"a","texte":"C’est l’exception à la règle du verbe final de la subordonnée"},{"id":"b","texte":"C’est parce que « lernen » est un verbe à particule séparable"},{"id":"c","texte":"C’est une faute d’inattention commise par l’élève dans son mail"},{"id":"d","texte":"C’est la règle normale de toutes les subordonnées en allemand"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Double infinitif : pas de participe.","type":"trous","segments":["Du weißt, dass ich nicht habe kommen ",0,"."],"banque":["gekonnt","können","kann","konnte"]},{"enonce":"Remets les mots dans l’ordre.","aide":"La conjonction ouvre la subordonnée, l’auxiliaire passe devant les infinitifs.","type":"ordre","items":[{"id":"a","texte":"weil"},{"id":"b","texte":"dich"},{"id":"c","texte":"anrufen"},{"id":"d","texte":"habe"},{"id":"e","texte":"können"},{"id":"f","texte":"ich"},{"id":"g","texte":"nicht"}]},{"enonce":"Quelle phrase est correcte pour « Clara n’a pas pu venir » ?","aide":"Auxiliaire « haben », puis deux infinitifs.","type":"choix","options":[{"id":"a","texte":"Clara hat nicht kommen können."},{"id":"b","texte":"Clara hat nicht kommen gekonnt."},{"id":"c","texte":"Clara ist nicht kommen können."},{"id":"d","texte":"Clara hat nicht gekommen gekonnt."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m31"]},"explication":"**habe** … **habe** : l’auxiliaire se place devant les deux infinitifs dans la subordonnée."},{"cle":{"type":"choix","ids":["a"]},"explication":"Avec un double infinitif, **l’auxiliaire conjugué passe devant** les deux infinitifs."},{"cle":{"type":"trous","trous":[["konnen"]]},"affichage":"können","explication":"**habe kommen können** : deux infinitifs, l’auxiliaire devant."},{"cle":{"type":"ordre","ids":["a","f","b","g","d","c","e"]},"explication":"**weil ich dich nicht habe anrufen können** : auxiliaire avant les deux infinitifs."},{"cle":{"type":"choix","ids":["a"]},"explication":"**hat nicht kommen können** : double infinitif avec « haben »."}]$ex$::jsonb),
