   $ex${"titre":"Ce que dit le journal","competence":"analyser-texte","situation":"Un article rapporte les propos d’un ministre. Lis-le, en repérant les verbes.","documents":[{"id":"zeitung","type":"texte","genre":"article","titre":"Der Minister ist krank","blocs":["Der Minister sagte gestern, er sei krank. Seine Sprecherin erklärte, er habe Fieber und könne nicht kommen. Die Opposition meint, er habe die Sitzung nur vermeiden wollen.","Laut der Zeitung gab es im Saal viele leere Stühle."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les quatre verbes au subjonctif I.","aide":"Ils suivent « er » dans des propos rapportés : sei, habe, könne…","type":"zone","document":"zeitung","multiple":true},{"enonce":"À quoi sert le subjonctif I dans cet article ?","aide":"Le journaliste rapporte ce que d’autres disent.","type":"choix","options":[{"id":"a","texte":"À exprimer le souhait irréel du journaliste sur le ministre"},{"id":"b","texte":"À donner un ordre précis aux lecteurs de ce journal"},{"id":"c","texte":"À raconter des faits certains qui se sont passés hier"},{"id":"d","texte":"À signaler qu’on rapporte des propos sans les garantir"}],"multiple":false},{"enonce":"Associe chaque parole d’origine à son discours rapporté.","aide":"On reprend le verbe à la 3e personne du subjonctif I.","type":"association","gauche":[{"id":"g0","texte":"Ich bin krank."},{"id":"g1","texte":"Ich habe Fieber."},{"id":"g2","texte":"Ich kann nicht kommen."}],"droite":[{"id":"d0","texte":"Er sagt, er könne nicht kommen."},{"id":"d1","texte":"Er sagt, er sei krank."},{"id":"d2","texte":"Er sagt, er habe Fieber."}]},{"enonce":"Que signifie « Laut der Zeitung … » ?","aide":"« laut » + datif introduit une source.","type":"choix","options":[{"id":"a","texte":"Selon le journal"},{"id":"b","texte":"Malgré le journal"},{"id":"c","texte":"À cause du journal"},{"id":"d","texte":"Au lieu du journal"}],"multiple":false}]}$ex$::jsonb,
