   $ex${"titre":"Visite à la East Side Gallery","competence":"analyser-texte","situation":"Un guide accueille des lycéens à Berlin. Lis son texte, écrit pour l’exercice.","documents":[{"id":"fuehrung","type":"texte","genre":"article","titre":"Willkommen an der East Side Gallery","blocs":["Dieser 1,3 Kilometer lange Rest der Berliner Mauer wurde 1990 von Künstlern aus der ganzen Welt bemalt. Die Mauer, die 1961 gebaut wurde, trennte Berlin fast dreißig Jahre lang.","Ein Stück weiter, in der Bernauer Straße, steht die offizielle Gedenkstätte. Dort erinnert man an die Menschen, die bei der Flucht gestorben sind. Wer die Spur der Mauer in der Stadt sucht, folgt der doppelten Pflasterreihe."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui signifie « mémorial ».","aide":"Il est composé de « gedenken » (commémorer) et de « Stätte » (lieu).","type":"zone","document":"fuehrung","multiple":false},{"enonce":"Quelle est la longueur du mur conservé à la East Side Gallery, en kilomètres ?","aide":"Regarde le début du premier paragraphe.","type":"nombre","unite":"km"},{"enonce":"Qui commémore-t-on à la Gedenkstätte de la Bernauer Straße ?","aide":"Relis la phrase « Dort erinnert man an… ».","type":"choix","options":[{"id":"a","texte":"Les artistes qui ont peint le mur en 1990"},{"id":"b","texte":"Les soldats morts pendant la Première Guerre"},{"id":"c","texte":"Les habitants de Berlin-Ouest pendant l’été 1961"},{"id":"d","texte":"Les personnes mortes en essayant de fuir"}],"multiple":false},{"enonce":"Associe chaque lieu à sa fonction.","aide":"Reprends les deux paragraphes.","type":"association","gauche":[{"id":"g0","texte":"East Side Gallery"},{"id":"g1","texte":"Bernauer Straße"},{"id":"g2","texte":"la double rangée de pavés"}],"droite":[{"id":"d0","texte":"un mur peint par des artistes"},{"id":"d1","texte":"le tracé du Mur dans la ville"},{"id":"d2","texte":"le mémorial officiel"}]},{"enonce":"Complète la phrase au passif.","aide":"Passif au prétérit : werden + participe II.","type":"trous","segments":["Die Mauer, die 1961 gebaut ",0,", trennte Berlin."],"banque":["wurde","wird","hat","wurden"]}]}$ex$::jsonb,
