   $ex${"titre":"Garder ou détruire ?","competence":"argumenter","situation":"Deux lycéens débattent du sort de Prora, l’immense complexe nazi de l’île de Rügen. Lis leurs points de vue, écrits pour l’exercice.","documents":[{"id":"debatte","type":"texte","genre":"article","titre":"Was tun mit Prora ?","blocs":["Jan: Prora, der riesige Bau der Nazis auf Rügen, sollte man abreißen. Was die Nazis gebaut haben, verdient keinen Platz in unserer Landschaft.","Mia: Ich finde, man muss ihn behalten und erklären. Wenn man alles zerstört, verschwinden auch die Beweise. Heute gibt es in Prora ein Dokumentationszentrum, in dem man lernt, wofür der Bau gedacht war."],"source":"Débat imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui signifie « les preuves ».","aide":"Mia dit que détruire fait disparaître quelque chose.","type":"zone","document":"debatte","multiple":false},{"enonce":"Quelle thèse Mia défend-elle ?","aide":"Relis « man muss ihn behalten und erklären ».","type":"choix","options":[{"id":"a","texte":"Il faut détruire le bâtiment le plus vite possible"},{"id":"b","texte":"Il faut conserver le bâtiment et l’expliquer"},{"id":"c","texte":"Il faut laisser le bâtiment sans aucune explication"},{"id":"d","texte":"Il faut vendre le bâtiment à une entreprise privée"}],"multiple":false},{"enonce":"Quel est l’argument de Jan ?","aide":"Relis la deuxième phrase de Jan.","type":"choix","options":[{"id":"a","texte":"Les constructions nazies attirent trop de touristes chaque année"},{"id":"b","texte":"Les constructions nazies ne méritent pas une place dans le paysage"},{"id":"c","texte":"Les constructions nazies n’ont jamais été terminées"},{"id":"d","texte":"Les constructions nazies coûtent trop cher à entretenir"}],"multiple":false},{"enonce":"Complète la phrase (condition).","aide":"La condition : « si on détruit tout ».","type":"trous","segments":[0," man alles zerstört, verschwinden die Beweise."],"banque":["Damit","Obwohl","Wenn","Bevor"]},{"enonce":"Range