  ('dfea713c-8373-5243-8d94-88b71193a786'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"De Salem à Hollywood","competence":"se-reperer-temps","situation":"Une brochure de théâtre explique pourquoi Arthur Miller a écrit *The Crucible*. Place les dates sur la frise et lis le texte.","documents":[{"id":"frise","type":"frise","titre":"The anti-communist years","debut":1940,"fin":1960,"pas":2,"evenements":[{"id":"z1","date":1947,"nom":"Hollywood Ten"},{"id":"z2","date":1950,"nom":"McCarthy"},{"id":"z3","date":1953,"nom":"The Crucible"}],"source":"Repères du cours"},{"id":"notice","type":"texte","genre":"article","titre":"Programme note","blocs":["Arthur Miller did not write a history lesson. In 1953 he set The Crucible in Salem, Massachusetts, in 1692, where nineteen people were hanged after accusations of witchcraft.","Audiences in 1953 understood at once: in their country, people were asked to name others as communists, and refusing could destroy a career. By telling the story of the past, Miller could criticise the present without naming it."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche sur la frise l’événement qui correspond à la création de la pièce de Miller.","aide":"Cherche le titre de la pièce.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent les procès de Salem (1692) de la pièce de Miller (1953) ?","aide":"Soustrais 1692 de 1953.","type":"nombre","unite":"ans"},{"enonce":"Touche le verbe qui montre que le public de 1953 a saisi l’allusion à son époque.","aide":"Il est juste après « Audiences in 1953 ».","type":"zone","document":"notice","multiple":true},{"enonce":"Pourquoi Miller choisit-il Salem ?","aide":"Relis la dernière phrase de la brochure.","type":"choix","options":[{"id":"a","texte":"Pour écrire une leçon d’histoire exacte et exhaustive"},{"id":"b","texte":"Pour défendre les juges qui avaient condamné les accusés"},{"id":"c","texte":"Pour faire de la publicité aux musées du Massachusetts"},{"id":"d","texte":"Pour critiquer sa propre époque sans avoir à la nommer"}],"multiple":false},{"enonce":"Complète la phrase de la brochure.","aide":"Après « without », le verbe prend la forme en -ing.","type":"trous","segments":["Miller could criticise the present without ",0," it."],"banque":["name","naming","named","to name"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**The Crucible** date de 1953, trois ans après le début de l’action de McCarthy."},{"cle":{"type":"nombre","valeur":261,"tolerance":0},"affichage":"261 ans","explication":"1953 − 1692 = **261** ans."},{"cle":{"type":"zone","ids":["m31"]},"explication":"Le public de 1953 **understood** at once : il a compris que Salem parlait de son présent."},{"cle":{"type":"choix","ids":["d"]},"explication":"Miller **critique le présent sans le nommer** : la fiction du passé lui sert de masque."},{"cle":{"type":"trous","trous":[["naming"]]},"affichage":"naming","explication":"On dit **without naming** : après une préposition, on emploie la forme en -ing."}]$ex$::jsonb),
