   $ex${"titre":"Bienvenue à Brightlake","competence":"analyser-texte","situation":"Une brochure vante « la ville la plus heureuse du monde ». Lis-la en cherchant ce qui cloche.","documents":[{"id":"brochure","type":"texte","genre":"article","titre":"Welcome to Brightlake","blocs":["Welcome to Brightlake, the happiest town in the world! Every street is spotless, every citizen has a job, and every home has a smart speaker that listens day and night, so that nothing is ever forgotten. Cameras in the parks keep you safe. Citizens who complain lose points on their Happiness Score, but why would anyone complain?"],"source":"Brochure imaginée pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui nomment des appareils qui écoutent ou observent les habitants.","aide":"L’un est dans chaque maison, l’autre dans les parcs.","type":"zone","document":"brochure","multiple":true},{"enonce":"Quel est le ton de cette brochure ?","aide":"Que se passe-t-il pour ceux qui se plaignent ?","type":"choix","options":[{"id":"a","texte":"Un enthousiasme officiel qui cache un contrôle inquiétant"},{"id":"b","texte":"Une critique violente de la ville par ses habitants révoltés"},{"id":"c","texte":"Un simple guide touristique sans rien d’étrange ni de menaçant"},{"id":"d","texte":"Une annonce publicitaire pour vendre des haut-parleurs connectés"}],"multiple":false},{"enonce":"Associe chaque mot à sa traduction.","aide":"Une dystopie est le contraire d’une utopie.","type":"association","gauche":[{"id":"g0","texte":"a utopia"},{"id":"g1","texte":"a dystopia"},{"id":"g2","texte":"a cautionary tale"},{"id":"g3","texte":"rags to riches"}],"droite":[{"id":"d0","texte":"une utopie"},{"id":"d1","texte":"un récit d’avertissement"},{"id":"d2","texte":"une dystopie"},{"id":"d3","texte":"de la misère à la fortune"}]},{"enonce":"Complète le commentaire.","aide":"Une société parfaite en façade mais oppressive.","type":"trous","segments":["Brightlake looks like a utopia, but it is a ",0," : its c