   $ex${"titre":"Danny, de la misère à la fortune ?","competence":"analyser-document","situation":"Un journal présente Danny Reyes comme un « self-made man ». Croise son portrait et le graphique de ses revenus.","documents":[{"id":"portrait","type":"texte","genre":"article","titre":"Danny Reyes","blocs":["Danny Reyes grew up in a small flat in Detroit. At 18 he worked nights in a warehouse. Seven years later he sold his first app, and by 32 his company employed fifty people.","Newspapers call him a self-made man, yet Danny admits that a teacher lent him his first laptop."],"source":"Texte écrit pour l’exercice"},{"id":"revenus","type":"graphique","forme":"barres","titre":"Danny’s yearly income","categories":["Age 18","Age 25","Age 32","Age 40"],"series":[{"nom":"Income","valeurs":[12,30,85,240],"teinte":"turquoise"}],"axeY":{"titre":"Income","unite":"in thousand dollars","min":0,"max":250,"pas":50},"axeX":{"titre":"Age"},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Quel revenu annuel, en milliers de dollars, Danny avait-il à 32 ans ?","aide":"Lis la hauteur de la troisième barre.","type":"nombre","unite":"k$"},{"enonce":"Touche la barre de la première année où Danny dépasse 100 000 dollars.","aide":"Cherche la première barre au-dessus de 100.","type":"zone","document":"revenus","multiple":false},{"enonce":"Combien de fois son revenu à 40 ans est-il plus élevé que celui à 25 ans ?","aide":"Divise 240 par 30.","type":"nombre"},{"enonce":"Quelle nuance le portrait apporte-t-il à l’expression « self-made man » ?","aide":"Relis la dernière phrase du portrait.","type":"choix","options":[{"id":"a","texte":"Sa réussite est fausse, car ses employés ont écrit l’application seuls"},{"id":"b","texte":"Sa réussite prouve que l’ascension sociale est possible pour chacun"},{"id":"c","texte":"Sa réussite doit aussi à l’aide d’un professeur, pas seulement à son travail"},{"id":"d","texte":"Sa réussite vient d’un héritage familial reçu à l’âge de dix-huit ans"}],"multiple":false},{"enonce":"Complète le commentaire.","aide":"De la misère à la fortune.","type":"trous","segments":["Danny’s story looks like a typical ",0," story, although he did not do it alone."],"banque":["rags to riches","upward","cautionary","dystopian"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":85,"tolerance":0},"affichage":"85 k$","explication":"La barre de **32 ans** atteint 85, soit 85 000 dollars."},{"cle":{"type":"zone","ids":["k3"]},"explication":"À 32 ans il est à 85 : c’est à **40 ans** (240) qu’il dépasse 100 000 dollars."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"240 ÷ 30 = **8** : son revenu à 40 ans est huit fois celui de ses 25 ans."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un professeur lui a prêté son premier ordinateur : **le mythe du self-made man est nuancé**."},{"cle":{"type":"trous","trous":[["rags to riches"]]},"affichage":"rags to riches","explication":"C’est une histoire **rags to riches**, mais avec un coup de pouce."}]$ex$::jsonb),
