   $ex${"titre":"Deux familles de fictions","competence":"analyser-document","situation":"Une élève prépare l’introduction d’une dissertation sur la fiction et le réel. Croise son texte avec un tableau d’œuvres.","documents":[{"id":"intro","type":"texte","genre":"article","titre":"Student’s introduction","blocs":["Fiction holds up a mirror to society, but it does not always show the same face. Dystopias exaggerate a real trend to warn us, whereas novels about the American Dream question a national promise that does not keep its word for everyone. This essay will compare both kinds of stories."],"source":"Texte écrit pour l’exercice"},{"id":"oeuvres","type":"tableau","titre":"Six works","colonnes":["Work","Author","Year","Theme"],"lignes":[["Nineteen Eighty-Four","George Orwell",1949,"Total surveillance"],["Fahrenheit 451","Ray Bradbury",1953,"A society that burns books"],["The Hunger Games","Suzanne Collins",2008,"Deadly games as television"],["The Great Gatsby","F. Scott Fitzgerald",1925,"Wealth cannot erase origins"],["Of Mice and Men","John Steinbeck",1937,"A dream of land that never comes"],["Death of a Salesman","Arthur Miller",1949,"A man broken by the ideal of success"]],"enteteLignes":false,"source":"Repères du cours"}],"questions":[{"enonce":"Range chaque œuvre dans la bonne famille.","aide":"Regarde la colonne « Theme » : surveillance, censure, spectacle d’un côté ; réussite qui échoue de l’autre.","type":"categories","categories":[{"id":"c0","texte":"Dystopie"},{"id":"c1","texte":"Rêve américain"}],"items":[{"id":"i0","texte":"Nineteen Eighty-Four"},{"id":"i1","texte":"Of Mice and Men"},{"id":"i2","texte":"The Great Gatsby"},{"id":"i3","texte":"Fahrenheit 451"},{"id":"i4","texte":"Death of a Salesman"},{"id":"i5","texte":"The Hunger Games"}]},{"enonce":"Combien d’années séparent *The Great Gatsby* de *Fahrenheit 451* ?","aide":"Soustrais l’année de Gatsby de celle de Fahrenheit 451.","type":"nombre","unite":"ans"},{"enonce":"Touche l’année de publication de l’œuvre la plus récente du tableau.","aide":"Cherche le plus grand nombre de la colonne « Year ».","type":"zone","document":"oeuvres","multiple":false},{"enonce":"Complète la phrase de l’introduction.","aide":"But de l’exagération ; puis opposition entre deux familles.","type":"trous","segments":["Dystopias exaggerate a real trend ",0," warn us, ",1," novels about the American Dream question a national promise."],"banque":["to","because","whereas","unless"]},{"enonce":"Quelle thèse relie le mieux le tableau et l’introduction ?","aide":"Vérifie chaque phrase avec les années et les thèmes du tableau.","type":"choix","options":[{"id":"a","texte":"Dystopias warn about the future, while American Dream novels question a national myth."},{"id":"b","texte":"Dystopias were all written after the year 2000 to criticise new technologies."},{"id":"c","texte":"Every work in the table was published in the United States during the 1950s."},{"id":"d","texte":"American Dream novels all celebrate success and never mention failure or poverty."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Les trois premières **dénoncent un futur exagéré** ; les trois autres **questionnent le rêve américain**."},{"cle":{"type":"nombre","valeur":28,"tolerance":0},"affichage":"28 ans","explication":"1953 − 1925 = **28** ans."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"*The Hunger Games* date de **2008**, la plus récente des six."},{"cle":{"type":"trous","trous":[["to"],["whereas"]]},"affichage":"to · whereas","explication":"**To warn** (but) et **whereas** (opposition : « alors que »)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Seule la première est **fidèle aux deux documents** : les autres sont contredites par les dates et les thèmes."}]$ex$::jsonb),
  ('cce272bb-dd9d-5d1f-ae77-8e408b3720c8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le mot du comité des fêtes","competence":"manier-langue","situation":"Le comité des fêtes remercie les bénévoles sur le site du lycée. Son texte utilise plusieurs inversions.","documents":[{"id":"mot","type":"texte","genre":"article","titre":"School fair — thank you!","blocs":["Never have we had so many volunteers at the school fair. Rarely does a festival attract such a crowd in November. Not only did the band play for free, but they also raised five hundred pounds for the library."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois auxiliaires qui ont été placés avant le sujet à cause de l’adverbe de début de phrase.","aide":"Dans chaque phrase, l’auxiliaire vient juste après l’adverbe.","type":"zone","document":"mot","multiple":true},{"enonce":"La phrase neutre est « She rarely complains. ». Complète la version avec inversion (présent).","aide":"Au présent simple, on appelle « do/does ».","type":"trous","segments":["Rarely ",0," she complain."],"banque":["has","did","is","does"]},{"enonce":"Associe chaque expression à sa traduction.","aide":"Ces quatre expressions déclenchent toutes l’inversion.","type":"association","gauche":[{"id":"g0","texte":"Seldom"},{"id":"g1","texte":"Hardly… when"},{"id":"g2","texte":"Under no circumstances"},{"id":"g3","texte":"Only then"}],"droite":[{"id":"d0","texte":"à peine… que"},{"id":"d1","texte":"en aucun cas"},{"id":"d2","texte":"ce n’est qu’alors que"},{"id":"d3","texte":"rarement"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m12","m23"]},"explication":"Ce sont **have**, **does** et **did** : après *Never*, *Rarely* et *Not only*, l’auxiliaire passe avant le sujet."},{"cle":{"type":"trous","trous":[["does"]]},"affichage":"does","explication":"Sans auxiliaire, on utilise **does** : *Rarely does she complain.*"},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**Seldom** = rarement ; **Hardly… when** = à peine… que ; **Under no circumstances** = en aucun cas."}]$ex$::jsonb),
  ('cce272bb-dd9d-5d1f-ae77-8e408b3720c8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Corriger les copies","competence":"manier-langue","situation":"Tu corriges six phrases d’un devoir d’élèves. Trois sont justes, trois contiennent une faute d’inversion.","documents":[{"id":"copies","type":"tableau","titre":"Six sentences from a class essay","colonnes":["N°","Sentence"],"lignes":[["1","Never I have seen a politician so honest."],["2","Rarely does the council listen to young people."],["3","No sooner had the results been announced when protests began."],["4","Not only is the law unfair, but it is also outdated."],["5","Under no circumstances the police should enter without a warrant."],["6","Little did the voters know what was coming."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les trois phrases incorrectes.","aide":"Vérifie dans chaque phrase : l’auxiliaire est-il avant le sujet ? Le bon mot de liaison suit-il ?","type":"zone","document":"copies","multiple":true},{"enonce":"Quelle faute contient la phrase 3 ?","aide":"« Hardly » va avec « when ». Et « No sooner » ?","type":"choix","options":[{"id":"a","texte":"Il faut « as » après « No sooner », pas « when »"},{"id":"b","texte":"Il faut un auxiliaire « did » après « No sooner »"},{"id":"c","texte":"Il faut « than » après « No sooner », pas « when »"},{"id":"d","texte":"Il faut supprimer l’inversion après « No sooner »"}],"multiple":false},{"enonce":"Corrige la phrase 1.","aide":"Le verbe « seen » est un participe passé.","type":"trous","segments":["Never ",0," I seen a politician so honest."],"banque":["do","am","have","did"]},{"enonce":"Remets les mots dans l’ordre pour former la phrase.","aide":"Après « Little », l’auxiliaire précède le sujet.","type":"ordre","items":[{"id":"a","texte":"imagine"},{"id":"b","texte":"did"},{"id":"c","texte":"Little"},{"id":"d","texte":"the"},{"id":"e","texte":"they"},{"id":"f","texte":"consequences"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r2c1","r4c1"]},"explication":"Fautes : phrase **1** (pas d’inversion), phrase **3** (« than » et non « when ») et phrase **5** (*should the police…*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**No sooner… than** : c’est la faute classique."},{"cle":{"type":"trous","trous":[["have"]]},"affichage":"have","explication":"*Never have I seen* : auxiliaire **have** avant le sujet."},{"cle":{"type":"ordre","ids":["c","b","e","a","d","f"]},"explication":"**Little did they imagine the consequences.**"}]$ex$::jsonb),
  ('cce272bb-dd9d-5d1f-ae77-8e408b3720c8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La lettre de réclamation","competence":"manier-langue","situation":"M. Turner écrit à son fournisseur d’accès. Sa lettre emploie l’inversion dans la condition. Croise-la avec son dossier client.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Mr Turner’s letter","blocs":["Dear Sir or Madam,","I am writing to complain about the broadband service I have received since March. Never have I experienced such unreliable service. Had your technician arrived on the agreed date, the problem would have been solved in a day. Not only did he fail to come, but nobody informed me.","Should you wish to keep me as a customer, I expect a full refund. Were the company to ignore this letter, I would contact the regulator.","Yours faithfully, J. Turner"],"source":"Lettre imaginée pour l’exercice"},{"id":"dossier","type":"tableau","titre":"Customer file","colonnes":["Date","Event"],"lignes":[["3 March","Line goes down"],["5 March","Visit booked for 10 March"],["10 March","Nobody comes"],["24 March","Complaint letter sent"]],"enteteLignes":false,"source":"Dossier imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui remplacent « if » dans une condition.","aide":"Ils sont en tête de phrase, sans « if ».","type":"zone","document":"lettre","multiple":true},{"enonce":"Combien de phrases de la lettre (hors formules de politesse) commencent par une inversion ?","aide":"Compte : Never, Had, Not only, Should, Were.","type":"nombre"},{"enonce":"Touche l’événement du dossier qui montre que la condition de « Had your technician arrived… » n’a pas été remplie.","aide":"Le technicien est-il venu à la date convenue ?","type":"zone","document":"dossier","multiple":false},{"enonce":"Quelle phrase a le même sens que « Had your technician arrived on the agreed date » ?","aide":"L’inversion avec « Had » remplace « if » + past perfect.","type":"choix","options":[{"id":"a","texte":"When your technician arrived on the agreed date"},{"id":"b","texte":"If your technician arrived on the agreed date"},{"id":"c","texte":"If your technician would have arrived on the agreed date"},{"id":"d","texte":"If your technician had arrived on the agreed date"}],"multiple":false},{"enonce":"Complète la phrase de la lettre.","aide":"Forme : « Were + sujet + to + verbe », puis un conditionnel.","type":"trous","segments":["Were the company ",0," ignore this letter, I ",1," contact the regulator."],"banque":["to","was","would","will"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m53","m67"]},"explication":"**Had**, **Should** et **Were** : trois inversions conditionnelles (*If your technician had arrived…*, *If you should wish…*, *If the company were to…*)."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"**5** phrases : *Never have I*, *Had your technician*, *Not only did he*, *Should you wish*, *Were the company*."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"« **Nobody comes** » le 10 mars : le technicien n’est pas venu, d’où la phrase contrefactuelle."},{"cle":{"type":"choix","ids":["d"]},"explication":"**If + past perfect** : *Had he arrived* = *If he had arrived*."},{"cle":{"type":"trous","trous":[["to"],["would"]]},"affichage":"to · would","explication":"*Were the company **to** ignore… I **would** contact…* : hypothèse peu probable."}]$ex$::jsonb),
  ('bcd86911-66dd-5708-b98d-1eb631b7273d'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le mail avant la sortie à York","competence":"manier-langue","situation":"Le proviseur écrit aux parents avant la sortie scolaire. Son mail est écrit dans un anglais soutenu.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Mr Hart’s email","blocs":["Dear parents,","Our school trip to York takes place on Friday. It is essential that every pupil arrive by 8:30. We insist that no phone be used on the coach. The governors recommend that parents sign the consent form, and it is vital that nobody forget the packed lunch.","Yours sincerely, Mr Hart"],"source":"Mail imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les quatre verbes à la base verbale (subjonctif) qui suivent « that ».","aide":"Aucun de ces verbes ne prend de -s, même avec « every pupil » ou « nobody ».","type":"zone","document":"mail","multiple":true},{"enonce":"Pourquoi écrit-on « that every pupil arrive » et non « arrives » ?","aide":"Regarde le déclencheur : « It is essential that ».","type":"choix","options":[{"id":"a","texte":"Parce que « pupil » est un nom pluriel dans cette phrase"},{"id":"b","texte":"Parce que l’anglais n’accorde jamais les verbes au présent"},{"id":"c","texte":"Après une expression d’exigence, on emploie la base verbale"},{"id":"d","texte":"Parce que l’école a voulu employer le futur de politesse"}],"multiple":false},{"enonce":"Complète la phrase à la négation.","aide":"Au subjonctif, la négation se fait sans « do ».","type":"trous","segments":["We suggest that he ",0," travel alone."],"banque":["won’t","doesn’t","not","isn’t"]},{"enonce":"Associe chaque formule figée à sa traduction.","aide":"Le subjonctif survit dans ces expressions figées.","type":"association","gauche":[{"id":"g0","texte":"God save the King"},{"id":"g1","texte":"Be that as it may"},{"id":"g2","texte":"So be it"},{"id":"g3","texte":"Long live the Queen"}],"droite":[{"id":"d0","texte":"Que Dieu sauve le roi"},{"id":"d1","texte":"Ainsi soit-il"},{"id":"d2","texte":"Quoi qu’il en soit"},{"id":"d3","texte":"Vive la reine"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m26","m36","m46"]},"explication":"**arrive**, **be**, **sign**, **forget** : après exiger, recommander ou « it is essential », on emploie la base verbale."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est un **subjonctif** : après *essential*, *insist*, *recommend*, le verbe reste à la base."},{"cle":{"type":"trous","trous":[["not"]]},"affichage":"not","explication":"**Not** + base verbale : *that he not travel alone*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"Dans ces formules, **save**, **be** et **live** sont des subjonctifs sans -s."}]$ex$::jsonb),
  ('bcd86911-66dd-5708-b98d-1eb631b7273d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Il parle comme s’il savait tout","competence":"comprendre-langue","situation":"Deux amis discutent d’un camarade qui se croit expert en musique. Observe les verbes au prétérit qui ne parlent pas du passé.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Jake talks as if he knew everything about music."},{"qui":"Sam","texte":"I’d rather he stayed quiet, honestly."},{"qui":"Nina","texte":"It’s high time somebody told him. If I were you, I’d say it to his face."}]}],"questions":[{"enonce":"Touche les quatre verbes au prétérit qui expriment l’irréel ou un souhait, et non un fait passé.","aide":"Jake ne sait pas tout ; Sam ne parle pas d’hier.","type":"zone","document":"sms","multiple":true},{"enonce":"Que souhaite Sam avec « I’d rather he stayed quiet » ?","aide":"« I’d rather + sujet + prétérit » exprime une préférence.","type":"choix","options":[{"id":"a","texte":"Il constate que Jake est resté silencieux"},{"id":"b","texte":"Il préférerait que Jake se taise"},{"id":"c","texte":"Il préfère rester lui-même silencieux ici"},{"id":"d","texte":"Il demande à Jake de rester après la fête"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Après « It’s high time », on emploie le prétérit.","type":"trous","segments":["It’s high time we ",0," home."],"banque":["went","going","to go","will go"]},{"enonce":"Associe chaque réplique à sa traduction.","aide":"Dans chaque cas, le prétérit anglais correspond à un subjonctif français.","type":"association","gauche":[{"id":"g0","texte":"Jake talks as if he knew everything"},{"id":"g1","texte":"I’d rather he stayed quiet"},{"id":"g2","texte":"It’s high time somebody told him"},{"id":"g3","texte":"If I were you"}],"droite":[{"id":"d0","texte":"Jake parle comme s’il savait tout"},{"id":"d1","texte":"Je préférerais qu’il se taise"},{"id":"d2","texte":"À ta place"},{"id":"d3","texte":"Il est grand temps que quelqu’un le lui dise"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m12","m19","m23"]},"explication":"**knew**, **stayed**, **told**, **were** : après *as if*, *I’d rather*, *it’s high time* et *if*, le prétérit dit l’irréel."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Il préférerait que Jake se taise** : *I’d rather you stayed* = je préférerais que tu restes."},{"cle":{"type":"trous","trous":[["went"]]},"affichage":"went","explication":"*It’s high time we **went** home* : il est grand temps que nous rentrions."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Le prétérit de l’irréel se traduit par un **subjonctif** ou un conditionnel en français."}]$ex$::jsonb),
  ('bcd86911-66dd-5708-b98d-1eb631b7273d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le rapport de la commission","competence":"manier-langue","situation":"Une commission municipale publie son rapport sur la bibliothèque. Sa rédaction mêle les trois manières d’exprimer le subjonctif.","documents":[{"id":"rapport","type":"texte","genre":"article","titre":"Library panel report","blocs":["The panel recommends that the library remain open on Sundays. Members insisted that the budget be published before the vote. They also suggest that the council should fund the plan. It is high time the council looked at the real figures, and some members speak as if the library were a luxury."],"source":"Texte écrit pour l’exercice"},{"id":"brouillons","type":"tableau","titre":"Five drafts from a class","colonnes":["N°","Draft"],"lignes":[["1","It is vital that they be informed in writing."],["2","She insisted that he to apologise."],["3","I suggest that she should see a doctor."],["4","It is vital that they being informed."],["5","We demand that the report be made public."]],"enteteLignes":false,"source":"Brouillons imaginés pour l’exercice"}],"questions":[{"enonce":"Range chaque passage du rapport selon la forme employée.","aide":"Cherche « should », une base verbale sans -s, un prétérit après « high time » ou « as if ».","type":"categories","categories":[{"id":"c0","texte":"Base verbale"},{"id":"c1","texte":"Should"},{"id":"c2","texte":"Prétérit irréel"}],"items":[{"id":"i0","texte":"speak as if the library were a luxury"},{"id":"i1","texte":"suggest that the council should fund the plan"},{"id":"i2","texte":"insisted that the budget be published"},{"id":"i3","texte":"It is high time the council looked at the real figures"},{"id":"i4","texte":"recommends that the library remain open"}]},{"enonce":"Touche les deux brouillons qui contiennent une forme impossible en anglais.","aide":"Après « that », ni « to + verbe » ni « being » ne fonctionnent ici.","type":"zone","document":"brouillons","multiple":true},{"enonce":"Pourquoi le brouillon 3 est-il correct alors qu’il n’a pas de base verbale ?","aide":"Relis la phrase du rapport avec « should fund ».","type":"choix","options":[{"id":"a","texte":"Parce que « suggest » n’exige aucune forme particulière après lui"},{"id":"b","texte":"Parce que « see » est un verbe irrégulier à la troisième personne"},{"id":"c","texte":"L’anglais britannique remplace souvent le subjonctif par should"},{"id":"d","texte":"Parce que le sujet « she » rend le verbe toujours invariable ici"}],"multiple":false},{"enonce":"Traduis : « Il est grand temps que la ville agisse. »","aide":"Après « high time », le verbe est au prétérit.","type":"trous","segments":["It’s high time the city ",0,"."],"banque":["acted","acts","act","will act"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c2","i4":"c0"}},"explication":"**remain** et **be** : base verbale ; **should fund** : alternative britannique ; **looked** et **were** : prétérit irréel."},{"cle":{"type":"zone","ids":["r1c1","r3c1"]},"explication":"Phrase **2** (*that he to apologise*) et phrase **4** (*that they being informed*) : ces formes n’existent pas."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Should** est l’alternative britannique courante : *I suggest that she should see a doctor*."},{"cle":{"type":"trous","trous":[["acted"]]},"affichage":"acted","explication":"*It’s high time the city **acted*** : prétérit à valeur de subjonctif."}]$ex$::jsonb),
  ('8b0e08dd-a283-592b-8038-b01ba17315c5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vieux pont de Riverton","competence":"comprendre-langue","situation":"Un journal local parle du pont de Riverton. Repère comment il dit ce qui doit être fait, ce qui a été fait et ce qui aurait dû l’être.","documents":[{"id":"pont","type":"texte","genre":"article","titre":"Riverton Gazette","blocs":["The old bridge in Riverton must be repaired before winter. It is said to have been built in 1890 and, for years, it has been looked after by volunteers. The residents should have been warned about the cracks, the mayor admits."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui suit « must » dans « must ___ repaired ».","aide":"C’est l’auxiliaire qui porte le passif.","type":"zone","document":"pont","multiple":true},{"enonce":"Que signifie « It is said to have been built in 1890 » ?","aide":"« is said to have been » parle du passé et d’une rumeur.","type":"choix","options":[{"id":"a","texte":"On dit qu’il a été construit en 1890"},{"id":"b","texte":"Il dit avoir construit le pont en 1890"},{"id":"c","texte":"Il est obligé de construire en 1890"},{"id":"d","texte":"On dit qu’il sera construit en 1890"}],"multiple":false},{"enonce":"Les bénévoles s’en occupent depuis des années (look after = s’occuper de). Complète.","aide":"La particule reste collée au verbe.","type":"trous","segments":["The bridge has been looked ",0," by volunteers for years."],"banque":["for","at","after","up"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**be** : avec un modal, le passif se forme *modal + be + participe passé*."},{"cle":{"type":"choix","ids":["a"]},"explication":"« **On dit qu’il a été construit en 1890** » : *is said to have been* + participe passé."},{"cle":{"type":"trous","trous":[["after"]]},"affichage":"after","explication":"Le passif garde la particule : **looked after**."}]$ex$::jsonb),
  ('8b0e08dd-a283-592b-8038-b01ba17315c5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Piratage au collège","competence":"analyser-texte","situation":"Un article rapporte une attaque informatique. Repère les passifs : qui a fait quoi ?","documents":[{"id":"hack","type":"texte","genre":"article","titre":"School network attacked","blocs":["Hackers are believed to have entered the school network on Monday. No data can be recovered, the head says, but parents will be informed today. The problem ought to have been noticed earlier, and students were told to change their passwords. Staff were made to stay late to check the systems."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que l’identité des pirates n’est pas prouvée.","aide":"Cherche un verbe d’opinion au passif.","type":"zone","document":"hack","multiple":true},{"enonce":"Que reproche l’article à l’équipe du collège ?","aide":"Cherche « ought to have ».","type":"choix","options":[{"id":"a","texte":"D’avoir informé les parents avant les élèves"},{"id":"b","texte":"D’avoir recruté des pirates pour tester le réseau"},{"id":"c","texte":"D’avoir changé les mots de passe sans prévenir"},{"id":"d","texte":"De ne pas avoir repéré le problème assez tôt"}],"multiple":false},{"enonce":"Associe chaque phrase du texte à sa version active.","aide":"Le sujet du passif devient le complément de l’actif.","type":"association","gauche":[{"id":"g0","texte":"Students were told to change their passwords"},{"id":"g1","texte":"Staff were made to stay late"},{"id":"g2","texte":"Parents will be informed today"},{"id":"g3","texte":"The problem ought to have been noticed earlier"}],"droite":[{"id":"d0","texte":"The head made staff stay late"},{"id":"d1","texte":"The school will inform parents today"},{"id":"d2","texte":"Someone ought to have noticed the problem earlier"},{"id":"d3","texte":"The school told students to change their passwords"}]},{"enonce":"Complète avec les mots de la banque.","aide":"Modal + be ; make au passif + to.","type":"trous","segments":["No data can ",0," recovered, and staff were made ",1," stay late."],"banque":["to","be","been","for"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"**Believed** : « on pense que » ; l’article ne fait que rapporter une hypothèse."},{"cle":{"type":"choix","ids":["d"]},"explication":"« *The problem ought to have been noticed earlier* » : **on aurait dû le repérer plus tôt**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Chaque passif déplace le complément en sujet ; **was made to** garde le « to » au passif."},{"cle":{"type":"trous","trous":[["be"],["to"]]},"affichage":"be · to","explication":"*can **be** recovered* (modal + be) et *were made **to** stay* (le « to » réapparaît)."}]$ex$::jsonb),
  ('8b0e08dd-a283-592b-8038-b01ba17315c5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La digue que personne n’a surveillée","competence":"analyser-document","situation":"Une digue a cédé dans une ville imaginaire. Croise le journal de bord de l’incident et la note de la commission d’enquête.","documents":[{"id":"journal","type":"tableau","titre":"Incident log — Dykeside","colonnes":["Date","Event","Result"],"lignes":[["3 March","Residents complain about cracks","Nobody replies"],["10 March","Inspection planned","Cancelled by the council"],["21 March","Dyke collapses","Forty homes flooded"]],"enteteLignes":false,"source":"Journal imaginé pour l’exercice"},{"id":"enquete","type":"texte","genre":"article","titre":"Extract from the inquiry note","blocs":["The inquiry found that the dyke had been poorly maintained for years. The residents should have been warned, and the complaints ought to have been dealt with. Instead, an inspection was cancelled and nobody was held responsible."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre qu’une plainte n’a reçu aucune réponse.","aide":"Regarde la colonne « Result » de la première ligne.","type":"zone","document":"journal","multiple":false},{"enonce":"Combien de jours s’écoulent entre la première plainte et l’effondrement de la digue ?","aide":"Soustrais 3 de 21.","type":"nombre","unite":"jours"},{"enonce":"Complète la phrase de la note d’enquête.","aide":"Modal du passé : should + have + been + participe.","type":"trous","segments":["The residents should ",0," ",1," warned."],"banque":["been","be","being","have"]},{"enonce":"Quel est le passif naturel de « The council gave the residents no information » ?","aide":"Avec deux compléments, on met la personne en sujet.","type":"choix","options":[{"id":"a","texte":"The information was not given the residents by the council."},{"id":"b","texte":"The residents were not given any information by the council."},{"id":"c","texte":"The residents were not give any information by the council."},{"id":"d","texte":"The residents did not be given any information by the council."}],"multiple":false},{"enonce":"Quelle phrase de la note d’enquête exprime une obligation qui n’a pas été respectée ?","aide":"Cherche un modal suivi de « have been ».","type":"choix","options":[{"id":"a","texte":"The dyke had been poorly maintained for years."},{"id":"b","texte":"The residents should have been warned."},{"id":"c","texte":"Nobody was held responsible."},{"id":"d","texte":"An inspection was cancelled."}],"multiple":false}]}$ex$::jsonb,
