   $ex${"titre":"Deux ados, deux parlements","competence":"comprendre-langue","situation":"Isla, de Glasgow, et Rhys, de Cardiff, se découvrent par messages avant un échange scolaire. Ils comparent leur façon d’être britanniques.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Isla","emoji":"👧","cote":"gauche"},{"nom":"Rhys","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Isla","texte":"Hi Rhys! I’m Scottish, but I feel British too: I can be both."},{"qui":"Rhys","texte":"Same here. In Wales, the Senedd decides on schools and hospitals, but defence and foreign policy stay in London."},{"qui":"Isla","texte":"It works the same way for us: Holyrood runs our schools and our health service."},{"qui":"Rhys","texte":"So Westminster has kept some powers and handed the others over to the nations."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs qu’Isla emploie pour dire qui elle est.","aide":"Cherche dans son premier message deux mots qui disent son appartenance.","type":"zone","document":"sms","multiple":true},{"enonce":"D’après Rhys, quels domaines restent entre les mains de Londres ?","aide":"Relis la fin du deuxième message : « … stay in London ».","type":"choix","options":[{"id":"a","texte":"L’organisation des hôpitaux écossais"},{"id":"b","texte":"La défense et la politique étrangère"},{"id":"c","texte":"Les programmes des écoles galloises"},{"id":"d","texte":"Le choix des règles dans les écoles"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Londres délègue des compétences sans renoncer à sa souveraineté.","type":"trous","segments":["This transfer of powers from London to Scotland and Wales is called ",0,"."],"banque":["secession","sovereignty","independence","devolution"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m7"]},"explication":"Isla se dit **Scottish** et **British** : on peut se sentir écossais et britannique à la fois."},{"cle":{"type":"choix","ids":["b"]},"explication":"Rhys le dit : **defence and foreign policy** restent à Londres, alors que les écoles et les hôpitaux relèvent des parlements des nations."},{"cle":{"type":"trous","trous":[["devolution"]]},"affichage":"devolution","explication":"C’est la **devolution** : Westminster confie des compétences aux nations sans perdre sa souveraineté."}]$ex$::jsonb),
