   $ex${"titre":"Les titres de la presse","competence":"comprendre-langue","situation":"Les journaux adorent fabriquer des mots. Lis quatre titres, puis une conversation où l’on transforme des noms en verbes.","documents":[{"id":"titres","type":"tableau","titre":"Four headlines","colonnes":["N°","Headline"],"lignes":[["A","Underfunded schools struggle as class sizes grow"],["B","City council to ban cars from the centre"],["C","Government plans to widen access to universities"],["D","Residents fear rebuilding will make the area unaffordable"]],"enteteLignes":false,"source":"Titres imaginés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Jade","emoji":"👩","cote":"gauche"},{"nom":"Noah","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Noah","texte":"Did you text Zoe about tonight?"},{"qui":"Jade","texte":"Yes, and I googled the address. I also emailed her the map."},{"qui":"Noah","texte":"Perfect. See you there!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le titre qui contient un verbe formé à partir d’un adjectif avec le suffixe -en.","aide":"Cherche un verbe qui vient de « wide ».","type":"zone","document":"titres","multiple":false},{"enonce":"Que signifie « underfunded » dans le titre A ?","aide":"under- veut dire « pas assez ».","type":"choix","options":[{"id":"a","texte":"Qui vient d’être financé de nouveau"},{"id":"b","texte":"Qui reçoit trop peu d’argent public"},{"id":"c","texte":"Qui n’a jamais reçu un seul euro"},{"id":"d","texte":"Qui reçoit trop d’argent public"}],"multiple":false},{"enonce":"Complète.","aide":"Le préfixe re- dit la répétition.","type":"trous","segments":["Rebuilding means building ",0,"."],"banque":["again","before","less","together"]},{"enonce":"Touche les trois verbes qui viennent d’un nom (conversion).","aide":"Un texto, Google, un e-mail : ce sont des noms à l’origine.","type":"zone","document":"sms","multiple":true}]}$ex$::jsonb,
