   $ex${"titre":"Le marché du travail décodé","competence":"analyser-texte","situation":"Cet article utilise plusieurs mots construits. Décode-les à l’aide du tableau, puis réponds aux questions.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Jobs for the young","blocs":["Jobs are scarce for young people. Many graduates, unable to find stable work, accept underpaid jobs and live in overcrowded shared flats. The government’s far-reaching reforms were meant to modernise the labour market, but critics call them overambitious. Most young workers feel powerless, and some have even become homeless."],"source":"Article écrit pour l’exercice"},{"id":"decode","type":"tableau","titre":"Decoding three words","colonnes":["Word","Parts","Meaning"],"lignes":[["overambitious","over + ambitious","too ambitious"],["underpaid","under + paid","?"],["homeless","home + less","without a home"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs formés avec le suffixe -less.","aide":"Cherche la terminaison -less.","type":"zone","document":"article","multiple":true},{"enonce":"Écris en un mot le nom anglais de « chômage » : un préfixe négatif + employ + un suffixe de nom.","aide":"Pense à un- + employ + -ment.","type":"texte"},{"enonce":"Comment traduire « far-reaching reforms » ?","aide":"Un mot composé : « far » + « reaching ».","type":"choix","options":[{"id":"a","texte":"Des réformes de grande portée"},{"id":"b","texte":"Des réformes importées de l’étranger"},{"id":"c","texte":"Des réformes qui n’aboutissent pas"},{"id":"d","texte":"Des réformes lointaines dans le temps"}],"multiple":false},{"enonce":"Quel jugement l’article rapporte-t-il sur les réformes ?","aide":"Regarde le mot « overambitious ».","type":"choix","options":[{"id":"a","texte":"Elles ont permis à tous les diplômés de trouver un emploi stable"},{"id":"b","texte":"Elles ont été abandonnées avant d’être officiellement présentées"},{"id":"c","texte":"Elles visaient trop haut et n’ont pas aidé les jeunes travailleurs"},{"id":"d","texte":"Elles étaient trop prudentes et ne changeaient presque rien"}],"multiple":false},{"enonce":"Complète : adjectif → verbe.","aide":"Suffixes de verbes : -en et -ify.","type":"trous","segments":["wide → to ",0," ; simple → to ",1],"banque":["widely","widen","simplify","simplicity"]},{"enonce":"Complète le tableau : que signifie « underpaid » ?","aide":"Regarde ce que veut dire under- dans le tableau.","type":"choix","options":[{"id":"a","texte":"Payé moins que ce qu’on devrait"},{"id":"b","texte":"Payé de nouveau une seconde fois"},{"id":"c","texte":"Payé avant d’avoir travaillé"},{"id":"d","texte":"Payé plus que ce qu’on devrait"}],"multiple":false}]}$ex$::jsonb,
