  ('07cfe4c0-994f-55e1-9a35-00c7d2c2f1be'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Léa à l’université","competence":"comprendre-langue","situation":"Léa, étudiante française, échange avec Tom, son correspondant anglais. Plusieurs mots de leur conversation sont des faux amis.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Hey Léa! Where are you?"},{"qui":"Léa","texte":"I’m in the library. I’m going to attend a lecture in ten minutes."},{"qui":"Tom","texte":"Actually, I thought you never got up early!"},{"qui":"Léa","texte":"Things change. It’s my first week at university."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre mots qui ressemblent à un mot français mais n’ont pas le même sens.","aide":"Library, attend, lecture, actually : relis les messages.","type":"zone","document":"sms","multiple":true},{"enonce":"Associe chaque mot anglais à son vrai sens.","aide":"Aucun de ces mots ne veut dire ce que son cousin français suggère.","type":"association","gauche":[{"id":"g0","texte":"library"},{"id":"g1","texte":"to attend"},{"id":"g2","texte":"a lecture"},{"id":"g3","texte":"actually"}],"droite":[{"id":"d0","texte":"une bibliothèque"},{"id":"d1","texte":"un cours magistral"},{"id":"d2","texte":"en fait"},{"id":"d3","texte":"assister à"}]},{"enonce":"Que veut dire Tom par « Actually, I thought you never got up early » ?","aide":"Tom est surpris : il croyait autre chose.","type":"choix","options":[{"id":"a","texte":"Actuellement, je crois que tu ne te lèves jamais tôt"},{"id":"b","texte":"En fait, je pensais le contraire de ce que je vois"},{"id":"c","texte":"Sans doute, tu ne te lèves jamais avant midi"},{"id":"d","texte":"Éventuellement, tu ne te lèves jamais assez tôt"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"« Il y a deux ans » se traduit sans « there is ».","type":"trous","segments":["I moved to Paris two years ",0,"."],"banque":["for","since","ago","before"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m12","m14","m18"]},"explication":"**library**, **attend**, **lecture** et **actually** sont des faux amis."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Un **library** est une bibliothèque, *to attend* = **assister à**, un **lecture** est un cours magistral, *actually* = **en fait**."},{"cle":{"type":"choix","ids":["b"]},"explication":"*Actually* = **en fait** : Tom croyait le contraire de ce qu’il découvre."},{"cle":{"type":"trous","trous":[["ago"]]},"affichage":"ago","explication":"« Il y a deux ans » = *two years **ago***."}]$ex$::jsonb),
