   $ex${"titre":"Le mail de Julie","competence":"manier-langue","situation":"Julie, étudiante à Londres, écrit à son hôte. Son message contient des calques du français.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Julie’s email","blocs":["Dear Mr Brown,","I am in London since Monday. Currently, I attend lectures at the university library, and the city is wonderful. Please give me some advices about cheap restaurants.","Yours sincerely, Julie"],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots fautifs dans le message de Julie.","aide":"Une faute de temps après « since », une faute sur un nom indénombrable.","type":"zone","document":"mail","multiple":true},{"enonce":"Corrige la première phrase.","aide":"Avec « since », on emploie le present perfect.","type":"trous","segments":["I ",0," ",1," in London since Monday."],"banque":["was","been","am","have"]},{"enonce":"Comment dire « Il a assisté à un cours magistral » ?","aide":"« To assist » veut dire « aider ».","type":"choix","options":[{"id":"a","texte":"He attended a lecture."},{"id":"b","texte":"He assisted at a lecture."},{"id":"c","texte":"He attended a reading."},{"id":"d","texte":"He waited for a lecture."}],"multiple":false},{"enonce":"Associe chaque expression française à sa traduction correcte.","aide":"Évite de traduire mot à mot.","type":"association","gauche":[{"id":"g0","texte":"Il y a deux ans"},{"id":"g1","texte":"Je suis ici depuis lundi"},{"id":"g2","texte":"Des conseils"},{"id":"g3","texte":"Plus de trente personnes"}],"droite":[{"id":"d0","texte":"two years ago"},{"id":"d1","texte":"I have been here since Monday"},{"id":"d2","texte":"more than thirty people"},{"id":"d3","texte":"some advice"}]}]}$ex$::jsonb,
