   $ex${"titre":"Version piégée","competence":"analyser-document","situation":"Un article de presse et un brouillon d’élève sont truffés de pièges de traduction. Croise-les pour ne pas tomber dedans.","documents":[{"id":"presse","type":"texte","genre":"article","titre":"The reform debate","blocs":["The minister claims that the reform will eventually help families, but she actually supports a plan that was criticised last year.","Critics say the public will be disappointed, not because of any deception, but because the chance of success is low."],"source":"Article écrit pour l’exercice"},{"id":"brouillon","type":"tableau","titre":"Student’s translations","colonnes":["N°","French","Student’s English"],"lignes":[["1","Il y a deux ans, j’ai assisté à ce match.","Two years ago, I assisted at this match."],["2","Je suis ici depuis lundi.","I am here since Monday."],["3","Il m’a donné des conseils.","He gave me some advice."],["4","Plus de trente personnes sont venues.","More than thirty people came."]],"enteteLignes":false,"source":"Brouillon écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux traductions incorrectes.","aide":"Deux erreurs : un faux ami et un présent à la place du present perfect.","type":"zone","document":"brouillon","multiple":true},{"enonce":"Corrige la traduction 1.","aide":"« Assister à » se dit autrement que « assist ».","type":"trous","segments":["Two years ago, I ",0," this match."],"banque":["waited","attended","assisted","helped"]},{"enonce":"Comment traduire la première phrase de l’article ?","aide":"« Eventually » = finalement, à terme.","type":"choix","options":[{"id":"a","texte":"La ministre attend que la réforme aide les familles"},{"id":"b","texte":"La ministre fait semblant que la réforme aidera éventuellement les familles"},{"id":"c","texte":"La ministre affirme que la réforme finira par aider les familles"},{"id":"d","texte":"La ministre s’est rendu compte que la réforme aide les familles"}],"multiple":false},{"enonce":"Touche les cinq faux amis de l’article.","aide":"Un adverbe, un verbe de soutien, une tromperie, une probabilité.","type":"zone","document":"presse","multiple":true},{"enonce":"Classe chaque phrase fautive selon la nature de l’erreur.","aide":"Un faux ami trompe sur le sens ; un calque copie la structure du français.","type":"categories","categories":[{"id":"c0","texte":"Faux ami"},{"id":"c1","texte":"Calque de structure"}],"items":[{"id":"i0","texte":"He gave me many advices."},{"id":"i1","texte":"She bought a book at the library."},{"id":"i2","texte":"I am here since Monday."},{"id":"i3","texte":"I assisted the lecture yesterday."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2","r1c2"]},"explication":"Erreurs : **assisted at** (il faut *attended*) et **I am here since** (il faut *I have been here since*)."},{"cle":{"type":"trous","trous":[["attended"]]},"affichage":"attended","explication":"*to attend* = assister à : *Two years ago, I **attended** this match.*"},{"cle":{"type":"choix","ids":["c"]},"explication":"*claims* = affirme, *eventually* = **finalement, à terme**, pas « éventuellement »."},{"cle":{"type":"zone","ids":["m7","m12","m13","m32","m36"]},"explication":"**eventually, actually, supports, deception, chance** : leur sens n’est pas celui des mots français proches."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Faux amis** : *assisted* (aider), *library* (bibliothèque, pas librairie). **Calques** : *am since* et *advices*."}]$ex$::jsonb),
  ('e57e3332-6f5c-5ed4-a8eb-c7ae36e9c1a4'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un musée à Liverpool","competence":"comprendre-langue","situation":"Liverpool était un grand port de la traite négrière. Lis le panneau d’un musée et repère les dates sur une frise.","documents":[{"id":"panneau","type":"texte","genre":"article","titre":"Museum panel","blocs":["This museum remembers the millions of enslaved people who were taken from Africa across the Atlantic between the sixteenth and the nineteenth centuries. Liverpool, once a major port of the slave trade, opened it in 2007 so that their stories would not be forgotten. Today, visitors can read the testimonies of descendants and discover how the city has come to terms with its past."],"source":"Panneau écrit pour l’exercice"},{"id":"frise","type":"frise","titre":"Timeline","debut":1800,"fin":2020,"pas":20,"evenements":[{"id":"z1","date":1807,"nom":"Trade abolished"},{"id":"z2","date":1833,"nom":"Abolition Act"},{"id":"z3","date":1865,"nom":"13th Amendment"},{"id":"z4","date":2007,"nom":"Liverpool museum"}],"source":"Dates arrondies à l’année"}],"questions":[{"enonce":"Touche les deux mots qui forment l’expression actuelle pour dire « les esclaves ».","aide":"On insiste sur le fait qu’ils ont été réduits en esclavage.","type":"zone","document":"panneau","multiple":true},{"enonce":"Touche l’événement de la frise qui se passe aux États-Unis.","aide":"Cherche le numéro d’un amendement.","type":"zone","document":"frise","multiple":false},{"enonce":"Pourquoi Liverpool a-t-elle ouvert ce musée ?","aide":"Cherche « so that… » dans le panneau.","type":"choix","options":[{"id":"a","texte":"Pour garder vivante la mémoire des personnes réduites en esclavage"},{"id":"b","texte":"Pour fêter la fin de la traite dans les colonies de la France"},{"id":"c","texte":"Pour accueillir les archives de la marine marchande américaine"},{"id":"d","texte":"Pour célébrer la réussite économique du grand port au XIXe siècle"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Un mémorial sert à se souvenir.","type":"trous","segments":["We visit a memorial to ",0," the victims."],"banque":["abolish","reclaim","control","commemorate"]}]}$ex$::jsonb,
