   $ex${"titre":"Juneteenth, une liberté qui arrive en retard","competence":"analyser-document","situation":"Le 19 juin est devenu une date nationale aux États-Unis. Lis l’article, puis repère la date dans un calendrier des commémorations.","documents":[{"id":"juneteenth","type":"texte","genre":"article","titre":"The story of Juneteenth","blocs":["On 19 June 1865, federal troops arrived in Galveston, Texas, and announced that all enslaved people were free, more than two years after the Emancipation Proclamation of 1 January 1863.","African Americans began to mark the date with parades, music and family picnics. In 2021, Juneteenth became a federal holiday."],"source":"Article écrit pour l’exercice"},{"id":"calendrier","type":"tableau","titre":"Commemoration calendar","colonnes":["Date","Commemoration","Where"],"lignes":[["11 November","Remembrance Day (poppy)","Commonwealth"],["25 April","ANZAC Day","Australia, New Zealand"],["19 June","Juneteenth","United States"],["30 September","Truth and Reconciliation Day","Canada"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Combien d’années séparent l’annonce de Galveston (1865) du jour férié fédéral (2021) ?","aide":"Soustrais 1865 de 2021.","type":"nombre","unite":"ans"},{"enonce":"Touche la date du calendrier qui correspond à l’événement raconté dans l’article.","aide":"L’article donne la date en toutes lettres : « 19 June ».","type":"zone","document":"calendrier","multiple":false},{"enonce":"Que suggère « more than two years after the Emancipation Proclamation » ?","aide":"Compare 1863 et 1865.","type":"choix","options":[{"id":"a","texte":"Que la fête est célébrée depuis plus de deux ans seulement"},{"id":"b","texte":"Que la proclamation a été signée à Galveston en 1865"},{"id":"c","texte":"Que les troupes fédérales ont refusé d’appliquer la proclamation"},{"id":"d","texte":"Que la liberté est arrivée très tard pour les derniers esclaves du Texas"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"La date est au passé.","type":"trous","segments":["Juneteenth ",0," a federal holiday in 2021."],"banque":["became","become","becoming","becomes"]}]}$ex$::jsonb,
